import {currentTheme,toggleTheme,setTheme,refreshThemeControls} from './theme.js';
import {codexConnectionPrompt} from './codex-connect.js';
import {AGENTS,STAGES,seedState,seedEpisode} from './data.js';
import {esc,safeUrl,icon,avatar,fmtTime,fmtDate,mmss,bytes,download,button,storyboardSvg} from './ui.js';
import {storyboardBatches,storyboardPrompt,boardAsset,boardMarkup,splitStoryboard,panelNames} from './storyboard.js';
import {referenceEditor,collectReference,referencePreview} from './references.js';
import {shotCsv,projectJson,exportBook,productionBook} from './exports.js';

let state=seedState(),revision=0,config={executionMode:'codex',bridgeReady:false,storageReady:false,signedIn:false},serverReady=false,loading=true;
const PAGES={overview:'Tổng quan',studio:'Xưởng sáng tạo',episodes:'Tập phim',library:'Thư viện tài nguyên',knowledge:'Tri thức & reference',team:'Đội ngũ agents',settings:'Thiết lập dự án'};
let page=PAGES[location.hash.slice(1)]?location.hash.slice(1):'studio',tab='studio',collabTab='chat',selected='ceo',sceneId='SC01',filter='all',query='',scope='episode',boardScene='all';
let saving=false,running=null,localRun=false,uploading=false,scene3d=null,renderToken=0,modalCtx={},draftNote='',returnFocus=null;
let sceneView=null;
const root=document.querySelector('#app');
window.addEventListener('valley-theme-change',()=>{scene3d?.setTheme(currentTheme());refreshThemeControls();});
const current=()=>state.episodes.find(e=>e.id===state.activeEpisode)||state.episodes[0];
const shots=e=>e.scenes.flatMap(s=>s.shots);
const countShots=e=>shots(e).length;
const duration=e=>shots(e).reduce((n,s)=>n+s.seconds,0);
let codexTasks=[];
const activeTask=(ep=current())=>codexTasks.find(t=>t.episodeId===ep.id&&t.stage===ep.stage&&['queued','running'].includes(t.status)&&!ep.outputs[ep.stage]);
const uploadLimit=()=>config.maxUploadBytes||30*1024*1024;
const uploadLimitLabel=()=>Math.floor(uploadLimit()/1024/1024)+' MiB';
const selectedAgent=()=>AGENTS.find(a=>a.id===selected)||AGENTS[0];
const uid=()=>crypto.randomUUID();
const pill=(text,type='')=>`<span class="pill ${type}">${text}</span>`;
const empty=(ico,title,text,action='',label='')=>`<div class="empty">${icon(ico)}<h3>${title}</h3><p>${text}</p>${action?button(action,label,'plus','soft'):''}</div>`;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'info':'check')+`<span>${esc(message)}</span>`;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
async function api(path,options={}){const response=await fetch(path,{...options,headers:options.body instanceof FormData?options.headers:{'content-type':'application/json',...options.headers}});let data;try{data=await response.json();}catch{throw new Error('Máy chủ chưa sẵn sàng. Dữ liệu hiện tại chưa được lưu.');}if(!response.ok)throw Object.assign(new Error(data.error||'Yêu cầu chưa thực hiện được.'),{status:response.status});return data;}
async function load(){try{config=await api('/api/config');if(config.storageReady&&config.signedIn){const result=await api('/api/state');state=result.state;revision=result.revision;serverReady=true;}}catch(error){console.info('Studio preview:',error.message);}loading=false;render();}
async function persist(){if(!serverReady)throw new Error('Chưa kết nối kho lưu trữ. Bạn vẫn có thể xem tập mẫu và xuất hồ sơ minh họa.');const result=await api('/api/state',{method:'PUT',body:JSON.stringify({state,revision})});revision=result.revision;state.updatedAt=result.updatedAt;}
async function mutate(fn,message='Đã lưu thay đổi.'){if(saving||uploading||running){toast('Studio đang xử lý. Vui lòng chờ hoàn tất.');return false;}const previous=structuredClone(state);saving=true;try{fn();await persist();if(message)toast(message);return true;}catch(error){state=previous;toast(error.message,true);if(error.status===409){try{const result=await api('/api/state');state=result.state;revision=result.revision;}catch{}}return false;}finally{saving=false;render();}}
function navigate(to){page=to;filter='all';query='';location.hash=to;closeModal();render();window.scrollTo({top:0,behavior:'smooth'});}
function render(){
 const token=++renderToken;if(scene3d){sceneView=scene3d.snapshot();scene3d.destroy();scene3d=null;}
 const ep=current();if(!ep)return;
 const nav=[['overview','grid'],['studio','studio'],['episodes','film'],['library','folder'],['knowledge','book'],['team','users']];
 root.innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="#studio" aria-label="Valley Studio"><img src="/assets/mark.svg" alt=""><div><div class="brand-name">valley<span>studio</span></div><small>SMALL STUDIO. BIG STORIES.</small></div></a><button class="project-switch" data-action="project"><span class="project-icon">${icon('mountain')}</span><span><strong>${esc(state.project.name)}</strong><small>Dự án phim của bạn</small></span>${icon('down')}</button><p class="nav-label">KHÔNG GIAN LÀM VIỆC</p><nav class="nav" aria-label="Điều hướng chính">${nav.map(([p,i])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}${PAGES[p]}${p==='episodes'?`<span class="count">${state.episodes.length.toString().padStart(2,'0')}</span>`:''}${p==='library'&&state.assets.length?`<span class="count">${state.assets.length}</span>`:''}</button>`).join('')}<div class="nav-divider"></div><button data-action="connect-codex">${icon('cloud')}Kết nối Codex</button><button data-page="settings" class="${page==='settings'?'active':''}">${icon('settings')}Thiết lập dự án</button></nav><div class="sidebar-bottom"><div class="small-garden">${icon('leaf')}<strong>Ươm những câu chuyện hay</strong><p>Một ý tưởng nhỏ hôm nay.<br>Một thước phim đẹp ngày mai.</p><button data-action="workflow-info">Khám phá quy trình ${icon('arrow')}</button></div><button class="user-card" data-action="account"><span class="user-avatar">Y</span><span><strong>${esc(config.displayName||'Nhà sáng tạo')}</strong><small>Không gian riêng của bạn</small></span>${icon('down')}</button></div></aside><div class="nav-scrim" data-action="close-nav"></div><div class="shell"><header class="topbar"><div class="row"><button class="icon-button mobile-toggle" data-action="menu" aria-label="Mở điều hướng">${icon('menu')}</button><div class="breadcrumb">${icon('mountain')}<span>${esc(state.project.name)}</span>${icon('chevron')}<strong>${PAGES[page]}</strong></div></div><div class="topbar-right"><button class="icon-button theme-toggle" data-action="toggle-theme" aria-label="Đổi giao diện sáng tối" aria-pressed="${currentTheme()==='dark'}">${currentTheme()==='dark'?'☀':'☾'}</button><span class="connection"><span class="dot ${config.bridgeReady?'':'muted'}"></span>Thực hiện qua Codex</span><button class="icon-button" data-action="notifications" aria-label="Hoạt động mới">${icon('bell')}</button><button class="icon-button" data-action="help" aria-label="Hướng dẫn">${icon('help')}</button></div></header><main class="main">${!serverReady?`<div class="hint-banner">${icon('info')}<span>${loading?'Đang kết nối studio…':config.signedIn?'Bản xem trước · Kho lưu trữ chưa sẵn sàng. Bạn có thể khám phá và xuất hồ sơ mẫu.':'Bản xem trước · Đăng nhập để lưu dự án và tải tư liệu.'}</span>${!config.signedIn?'<a href="/signin-with-chatgpt?return_to=/" target="_top">Đăng nhập →</a>':''}</div>`:''}${renderPage(ep)}<footer class="footer"><span>${icon('leaf')}Chậm lại một chút, để câu chuyện được kể trọn vẹn.</span><span class="status-saving">${serverReady?icon('cloud'):'◌'}${serverReady?'Đã lưu trên studio':'Đang xem tập minh họa'}</span></footer></main></div><input class="file-input" id="resource-files" type="file" multiple accept="image/jpeg,image/png,image/webp,image/avif,application/pdf,text/plain,text/markdown,.md,.txt,video/mp4,video/quicktime"><input class="file-input" id="import-json" type="file" accept="application/json,.json">`;
 if(page==='studio'&&tab==='studio'){const container=document.querySelector('#scene');import('./scene.js').then(m=>{if(token!==renderToken||!container?.isConnected)return;scene3d=m.mountScene(container,{onSelect:selectAgent,getStatus:()=>({selected,running}),view:sceneView});if(!scene3d)sceneFallback(container);else refreshSceneControls();}).catch(()=>sceneFallback(container));}
 refreshThemeControls();setupDrop();const chat=document.querySelector('.chat-content');if(chat)chat.scrollTop=chat.scrollHeight;
}
function refreshSceneControls(){const view=scene3d?.snapshot();if(!view)return;const motion=document.querySelector('[data-action="toggle-scene-motion"]'),orbit=document.querySelector('[data-action="auto-orbit"]');if(motion){motion.setAttribute('aria-pressed',String(!view.motionEnabled));motion.innerHTML=icon(view.motionEnabled?'pause':'play')+(view.motionEnabled?'Tạm dừng':'Bật chuyển động');}if(orbit)orbit.setAttribute('aria-pressed',String(view.autoOrbit));}
function sceneFallback(container){if(!container?.isConnected)return;container.innerHTML=`<div class="scene-fallback"><img src="/assets/mark.svg" alt=""><strong>Chào mừng đến xưởng phim của bạn</strong><p>Trình duyệt chưa bật WebGL.<br>Bạn vẫn có thể chọn cộng sự và làm việc ở bên dưới.</p></div>`;}
function heading(title,subtitle,actions='',eyebrow='YOUR CREATIVE SPACE'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function episodeBar(ep){return `<section class="episode-bar"><div class="episode-number">${String(ep.number).padStart(2,'0')}</div><div class="episode-title"><strong>${esc(ep.title)}</strong><small>${esc(ep.englishTitle||'Một câu chuyện đang được viết tiếp')} ${ep.sample?'· Tập minh họa':''}</small></div><div class="episode-meta"><span>${icon('clock')}${mmss(duration(ep))} mục tiêu dựng</span><span>${icon('film')}${ep.scenes.length} phân cảnh</span></div>${pill(ep.stage>=5?'Đã duyệt hồ sơ':'Đang tiền kỳ')}<button class="icon-button" data-action="switch-episode" aria-label="Chọn tập phim">${icon('down')}</button></section>`;}
function renderPage(ep){
 switch(page){case 'studio':return renderStudio(ep);case 'overview':return renderOverview(ep);case 'episodes':return renderEpisodes();case 'library':return renderLibrary();case 'knowledge':return renderKnowledge();case 'team':return renderTeam();case 'settings':return renderSettings();default:return '';}
}
function renderStudio(ep){
 const actions=button('edit-brief','Brief tập phim','edit')+button('export-menu','Xuất hồ sơ','download','primary');
 const tabs=[['studio','studio','Studio'],['script','file','Kịch bản'],['storyboard','board','Storyboard'],['deliverables','folder','Hồ sơ quay']];
 return heading('Xưởng sáng tạo','Nơi những ý tưởng bình dị trở thành câu chuyện đáng nhớ.',actions)+episodeBar(ep)+`<div class="tabs" role="tablist">${tabs.map(([t,i,label])=>`<button role="tab" aria-selected="${t===tab}" class="${t===tab?'active':''}" data-tab="${t}">${icon(i)}${label}${t==='storyboard'&&countShots(ep)?`<span class="tab-count">${countShots(ep)}</span>`:''}</button>`).join('')}</div>`+(tab==='studio'?studioMain(ep):tab==='script'?renderScript(ep):tab==='storyboard'?renderBoards(ep):renderDeliverables(ep));
}
function agentStatus(a,ep){const i=AGENTS.findIndex(x=>x.id===a.id),task=activeTask(ep);if(task?.agent===a.id){if(task.displayStatus==='interrupted')return {text:'Phiên tạm dừng',cls:'wait'};if(task.status==='queued')return {text:'Chờ Codex nhận',cls:'idle'};if(task.status==='running')return {text:'Codex đang làm',cls:'wait'};}if(running===a.id)return {text:'Đang chạy mẫu',cls:'wait'};if(ep.outputs[i]&&!ep.approved.includes(i))return {text:'Chờ bạn duyệt',cls:'wait'};if(ep.approved.includes(i))return {text:'Đã bàn giao',cls:''};if(i===ep.stage)return {text:'Sẵn sàng',cls:''};return {text:'Chờ bàn giao',cls:'idle'};}

function studioMain(ep){
 return `<div class="workspace-grid"><div class="workspace-left"><section class="panel scene-panel"><div class="panel-head"><h2>${icon('studio')}Một ngày ở Valley Studio</h2>${pill(`<span class="dot"></span>${running?'Agent đang xử lý':'5 cộng sự của bạn'}`)}</div><p class="scene-subtitle">Một xưởng phim nhỏ. Cùng nhau làm nên những câu chuyện lớn.</p><div class="scene-toolbar"><span class="scene-live"><span class="dot"></span>VALLEY · STUDIO 3D</span><div>${button('toggle-scene-motion','Tạm dừng','pause','small','aria-pressed="false"')}${button('auto-orbit','Tự xoay','refresh','small','aria-pressed="false"')}</div></div><div class="scene-viewport" id="scene"><div class="scene-fallback"><span class="spinner"></span><p>Đang chuẩn bị xưởng phim 3D…</p></div></div><div class="scene-controls"><button class="icon-button" data-action="zoom-out" aria-label="Thu nhỏ">${icon('minus')}</button><button class="icon-button" data-action="zoom-in" aria-label="Phóng to">${icon('plus')}</button><button class="icon-button" data-action="reset-scene" aria-label="Đặt lại góc nhìn">${icon('refresh')}</button><button class="icon-button" data-action="fullscreen-scene" aria-label="Mở toàn màn hình">${icon('expand')}</button></div><div class="scene-tip">${icon('mouse')}Kéo để xoay · Cuộn để zoom · Chọn cộng sự</div><div class="scene-foot"><span>${icon('sun')}Một xưởng nhỏ luôn có chuyển động</span><span>${icon('eye')}3D tương tác · ${running?'Đang chạy tác vụ':ep.sample?'Tập mẫu — chưa chạy AI':'Tiến độ theo hồ sơ'}</span></div></section><section class="team-section"><div class="section-label"><h2>Những cộng sự của bạn</h2><button data-page="team">Gặp cả đội ${icon('chevron')}</button></div><div class="agent-grid">${AGENTS.map(a=>{const status=agentStatus(a,ep);return `<button class="agent-card ${selected===a.id?'selected':''}" data-agent="${a.id}">${avatar(a)}<strong>${a.name}</strong><small>${a.short}</small><span class="agent-state ${status.cls}"><span class="dot"></span>${status.text}</span></button>`;}).join('')}</div></section>${renderWorkflow(ep)}</div><aside class="studio-aside">${renderCollab(ep)}${renderFilesPreview(ep)}</aside></div>`;
}
function renderWorkflow(ep){return `<section class="panel workflow-panel"><div class="panel-head"><h2>Hành trình của tập phim</h2><small>${ep.approved.length}/5 mốc đã duyệt</small></div><div class="workflow">${STAGES.map((s,i)=>`<button class="workflow-step ${ep.approved.includes(i)?'done':i===ep.stage?'current':''}" data-action="stage-detail" data-stage="${i}"><span class="step-circle">${ep.approved.includes(i)?icon('check'):i+1}</span>${s}</button>`).join('')}</div><div class="workflow-note">${icon('lock')}Bạn luôn là người duyệt trước khi cả đội đi tiếp.</div></section>`;}
function renderCollab(ep){
 const events=collabTab==='chat'?ep.activity.slice(-12):ep.activity.filter(a=>a.kind!=='note').slice(-18);
 const waiting=ep.outputs[ep.stage];const finished=ep.stage>=5;const pending=activeTask(ep);
 return `<section class="panel collab"><div class="collab-head"><h2>${icon('message')}Bàn chuyện cùng cả đội</h2><p>Ý tưởng của bạn. Chuyên môn của cộng sự.</p></div><div class="collab-tabs"><button class="${collabTab==='chat'?'active':''}" data-collab="chat">Trao đổi</button><button class="${collabTab==='activity'?'active':''}" data-collab="activity">Nhật ký hoạt động</button></div><div class="chat-content"><div class="date-line">Không gian của tập ${String(ep.number).padStart(2,'0')}</div>${events.map(ev=>{const a=AGENTS.find(a=>a.id===ev.agent),user=ev.kind==='note';return `<div class="chat-item">${user?'<span class="user-avatar" style="width:27px;height:27px;font-size:9px">Y</span>':avatar(a||AGENTS[0])}<div class="chat-item-content"><div class="chat-by">${user?'Bạn':a?.name||'Studio'}${!user?`<span class="mini-role">${a?.short||'Điều phối'}</span>`:''}<small>${fmtTime(ev.at)}</small></div><div class="chat-bubble ${user?'user':''}">${esc(ev.text)}${ev.kind==='sample'?'<div style="font-size:7px;opacity:.65;margin-top:7px">Nội dung minh họa · chưa phải kết quả AI thực tế</div>':''}${!user&&Object.values(ep.outputs).find(o=>o.at===ev.at)?`<button class="chat-result" data-action="stage-detail" data-stage="${AGENTS.findIndex(a=>a.id===ev.agent)}">${icon('file')}<span>Xem tài liệu bàn giao<small>${esc(AGENTS.find(a=>a.id===ev.agent)?.deliverable||'')}</small></span>${icon('chevron')}</button>`:''}</div></div></div>`;}).join('')}${running?`<div class="chat-item">${avatar(AGENTS.find(a=>a.id===running))}<div class="chat-bubble"><span class="spinner" style="display:inline-block;vertical-align:middle;margin-right:6px"></span>${AGENTS.find(a=>a.id===running)?.name} đang xử lý tư liệu…</div></div>`:''}</div>${!ep.notes.length?`<div class="chat-quick"><button data-action="note-preset" data-text="Ưu tiên âm thanh tự nhiên, hạn chế nhạc nền.">Ưu tiên âm thanh tự nhiên</button><button data-action="edit-brief">${icon('edit')} Chỉnh brief</button></div>`:''}${waiting&&!finished?`<div class="review-box"><strong>${AGENTS[ep.stage].name} đã bàn giao tài liệu</strong>${esc(waiting.summary)}<div class="review-buttons">${button('review-current','Xem & duyệt','eye','primary')}${button('revise-current','Góp ý','edit')}</div></div>`:''}${pending?codexTaskCard(pending):''}<div class="chat-compose"><div class="compose-target"><span class="dot" style="background:${selectedAgent().color}"></span>Gửi ghi chú cho ${selectedAgent().name} · ${selectedAgent().short}</div><form id="note-form"><div class="compose-box"><textarea id="note-text" aria-label="Ghi chú cho agent" placeholder="Chia sẻ ý tưởng, góp ý của bạn…" rows="2" maxlength="8000">${esc(draftNote)}</textarea><div class="compose-tools"><button type="button" class="icon-button" data-page="library" aria-label="Thêm tư liệu">${icon('paperclip')}</button><button type="submit" class="icon-button send" aria-label="Gửi ghi chú" ${running?'disabled':''}>${icon('send')}</button></div></div></form><div class="compose-footer">Ghi chú được đưa vào ngữ cảnh khi agent chạy.</div></div><div class="run-actions">${finished?button('export-menu','Mở hồ sơ đã duyệt','folder','primary'):!waiting?(pending?button('codex-task','Xem đầu việc Codex','clipboard','primary',`data-id="${esc(pending.id)}"`):button('run-codex','Giao việc cho Codex','send','primary')+(ep.sample?button('run-sample','Chạy mẫu','sparkles','sample-btn',running?'disabled':''):'')):''}</div></section>`;
}
function renderFilesPreview(ep){const artifacts=Object.values(ep.outputs).flatMap(o=>o.artifacts||[]);return `<section class="panel files-preview"><div class="panel-head"><h2>Tài liệu của tập</h2><small>${Object.keys(ep.outputs).length+artifacts.length+2} tệp</small></div><div class="file-row"><div class="file-icon">HTML</div><div><strong>Production book</strong><small>Kịch bản & storyboard · ${ep.stage>=5?'Đã duyệt':'Bản nháp'}</small></div><button class="icon-button" data-action="download-book" aria-label="Tải production book">${icon('download')}</button></div><div class="file-row"><div class="file-icon" style="background:#edf2e5;color:#91a57a">CSV</div><div><strong>Danh sách cảnh quay</strong><small>${countShots(ep)} shot chủ đạo · ${ep.scenes.length} phân cảnh</small></div><button class="icon-button" data-action="download-csv" aria-label="Tải shot list CSV">${icon('download')}</button></div>${Object.entries(ep.outputs).slice(-2).map(([i,o])=>`<div class="file-row"><div class="file-icon" style="background:#f0ecf3;color:#a696b2">TXT</div><div><strong>${esc(o.title)}</strong><small>${STAGES[Number(i)]} · ${ep.approved.includes(Number(i))?'Đã duyệt':'Chờ duyệt'}</small></div><button class="icon-button" data-action="download-output" data-stage="${i}" aria-label="Tải ${esc(o.title)}">${icon('download')}</button></div>`).join('')}${artifacts.map(a=>`<div class="file-row"><div class="file-icon">FILE</div><div><strong>${esc(a.name)}</strong><small>Codex tạo · ${bytes(a.size)}</small></div><a class="icon-button" href="${esc(a.url)}" download="${esc(a.name)}" aria-label="Tải tài liệu Codex">${icon('download')}</a></div>`).join('')}</section>`;}
function renderOverview(ep){const ready=state.episodes.filter(e=>e.stage>=5).length;return heading('Chào buổi sáng, nhà sáng tạo.','Một ngày mới. Một câu chuyện bình dị đang chờ được kể.',button('new-episode','Bắt đầu tập mới','plus','primary'),'WELCOME TO YOUR VALLEY')+`<div class="stats-grid">${[['film',state.episodes.length,'Tập phim đang ươm mầm'],['folder',state.assets.length,'Tài nguyên thực tế'],['users','05','Cộng sự trong xưởng'],['check',ready.toString().padStart(2,'0'),'Hồ sơ đã duyệt']].map(([i,n,l])=>`<div class="stat-card">${icon(i)}<strong>${n}</strong><small>${l}</small></div>`).join('')}</div><div class="overview-two"><section class="feature-card"><div class="eyebrow">STORIES GROW HERE</div><h2>Những câu chuyện lớn<br>từ điều nhỏ bé.</h2><p>Đưa ý tưởng và những hình ảnh đầu tiên vào xưởng. Cả đội sẽ cùng bạn xây nên hành trình của tập phim.</p>${button('open-studio','Vào xưởng sáng tạo','arrow','primary')}</section><section class="panel form-panel"><h2>Tập phim gần nhất</h2><div class="eyebrow">TẬP ${String(ep.number).padStart(2,'0')}</div><h2 style="font-size:22px;line-height:1.5;margin-bottom:12px">${esc(ep.title)}</h2><p class="text-small muted">${esc(ep.brief).slice(0,180)}…</p>${pill(ep.sample?'Tập minh họa':'Dự án thực tế',ep.sample?'amber':'')}<div style="margin-top:20px">${button('open-studio','Tiếp tục câu chuyện','chevron')}</div></section></div>${renderWorkflow(ep)}<div class="section-label" style="margin:25px 0 13px"><h2>Trước khi vào xưởng</h2><span>Một chút chuẩn bị, nhiều cảm hứng</span></div><div class="content-grid">${[['library','image','Thêm hình ảnh thực tế','Bối cảnh, nhân vật và đạo cụ là chất liệu để câu chuyện có thể quay thật.'],['knowledge','book','Gom điều bạn yêu thích','Lưu kỹ thuật quay, reference và ghi chú từ những kênh bạn học hỏi.'],['settings','compass','Giữ một tinh thần chung','Chốt khán giả, ngôn ngữ hình ảnh và nguyên tắc kể chuyện của dự án.']].map(([p,i,t,d])=>`<button class="panel form-panel" style="text-align:left" data-page="${p}">${icon(i)}<h3 style="font-size:12px;font-weight:500">${t}</h3><p class="text-small muted">${d}</p></button>`).join('')}</div>`;}
function renderEpisodes(){return heading('Những câu chuyện đang lớn','Mỗi tập phim là một chương mới trong hành trình ở thung lũng.',button('new-episode','Tạo tập phim','plus','primary'),'EPISODES & STORIES')+`<div class="content-grid">${state.episodes.map(ep=>`<article class="panel episode-card"><div class="episode-cover"><img src="${esc(ep.scenes[0]?.image||'/assets/valley.jpg')}" alt="Mood reference cho tập phim">${pill(ep.sample?'Tập minh họa':ep.stage>=5?'Đã duyệt hồ sơ':'Đang tiền kỳ')}</div><div class="resource-body"><div class="eyebrow">TẬP ${String(ep.number).padStart(2,'0')}</div><h3>${esc(ep.title)}</h3><p>${esc(ep.brief).slice(0,150)}${ep.brief.length>150?'…':''}</p><div class="resource-meta"><span>${ep.scenes.length} cảnh · ${countShots(ep)} shots</span><span>${ep.approved.length}/5 mốc đã duyệt</span></div>${button('open-episode','Tiếp tục trong xưởng','arrow','',`data-id="${esc(ep.id)}"`)}</div></article>`).join('')}<button class="empty" data-action="new-episode" style="grid-column:auto;min-height:330px">${icon('plus')}<h3>Một ý tưởng mới?</h3><p>Bắt đầu từ một câu chuyện thô.<br>Cả đội sẽ cùng bạn phát triển tiếp.</p></button></div>`;}
function renderLibrary(){const cats=[['all','Tất cả'],['context','Bối cảnh'],['character','Nhân vật'],['prop','Đạo cụ'],['knowledge','Tài liệu'],['reference','Reference'],['storyboard','Storyboard AI']];const ep=current();const all=state.assets.filter(a=>scope==='all'||(scope==='project'?!a.episodeId:!a.episodeId||a.episodeId===ep.id));const assets=all.filter(a=>(filter==='all'||a.category===filter)&&(!query||[a.name,a.description,a.tags].join(' ').toLowerCase().includes(query.toLowerCase())));return heading('Thư viện của những câu chuyện','Chất liệu thật cho một thế giới giàu cảm xúc. Lưu, phân loại và kết nối tư liệu với từng cảnh quay.',button('upload','Tải tài nguyên','upload','primary'),'YOUR CREATIVE LIBRARY')+`<div class="asset-scope">${icon('folder')}Phạm vi <select id="asset-scope" aria-label="Phạm vi thư viện"><option value="episode" ${scope==='episode'?'selected':''}>Dự án + Tập ${String(ep.number).padStart(2,'0')}</option><option value="project" ${scope==='project'?'selected':''}>Dùng chung toàn dự án</option><option value="all" ${scope==='all'?'selected':''}>Tất cả các tập</option></select><span class="spacer"></span><span>${all.length} tài nguyên · Lưu trên studio</span></div><div class="upload-drop" id="upload-drop">${icon('upload')}<h3>Kéo thả tài nguyên vào đây hoặc <button data-action="upload">chọn tệp</button></h3><p>Ảnh, PDF, TXT, Markdown, MP4 & MOV · Tối đa ${uploadLimitLabel()} mỗi tệp</p></div><div class="toolbar"><div class="filter-tabs">${cats.map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${label}${id==='all'?` · ${all.length}`:''}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search-input" aria-label="Tìm tài nguyên" placeholder="Tìm trong thư viện…" value="${esc(query)}"></label></div><div class="content-grid" id="resource-grid">${assets.length?assets.map(assetCard).join(''):empty('image',query?'Chưa tìm thấy tài nguyên':'Chất liệu đầu tiên cho câu chuyện',query?'Thử từ khóa khác hoặc thay bộ lọc.':'Tải ảnh căn nhà, khu vườn, hai chị em và đạo cụ thực tế. Codex sẽ đọc các tư liệu này để xây kịch bản có thể quay thật.',query?'':'upload','Thêm tư liệu đầu tiên')}</div>${!all.length&&!query&&filter==='all'?`<div class="section-label" style="margin-top:27px"><h2>Một chút cảm hứng cho thư viện</h2><span>Ảnh mood minh họa · không phải hiện trường</span></div><div class="content-grid">${[['valley','Thung lũng trong sương','Bối cảnh · Tư liệu mẫu'],['cabin','Một căn nhà giữa thiên nhiên','Không gian · Tư liệu mẫu'],['food','Bữa ăn giản dị','Đời sống · Tư liệu mẫu']].map(([img,t,sub])=>`<article class="resource-card"><div class="resource-thumb"><img src="/assets/${img}.jpg" alt="${t} — ảnh mood minh họa">${pill('MOOD REFERENCE','amber')}</div><div class="resource-body"><h3>${t}</h3><p>${sub}</p></div></article>`).join('')}</div><p class="license-note">Ảnh mood từ Unsplash, chỉ dùng làm ví dụ về cách tổ chức thư viện. Chúng chưa được dùng như dữ kiện của dự án.</p>`:''}<div class="instruction">${icon('info')} Codex đọc ảnh và tài liệu qua plugin của Xưởng. File qua MCP tối đa 5 MB mỗi lượt. PDF/video cần công cụ đọc phù hợp trong Codex; chỉ có metadata không có nghĩa là đã phân tích nội dung. Reference từ kênh khác nên có URL nguồn, timecode và ghi chú kỹ thuật bạn muốn học.</div>`;}
function assetCard(a){return `<article class="resource-card"><button class="resource-thumb" data-action="asset-detail" data-id="${esc(a.id)}" aria-label="Mở ${esc(a.name)}">${a.mime.startsWith('image/')?`<img src="${esc(a.url)}" loading="lazy" alt="${esc(a.name)}">`:icon(a.mime.startsWith('video/')?'film':a.mime==='application/pdf'?'file':'book')}${pill(({context:'Bối cảnh',character:'Nhân vật',prop:'Đạo cụ',knowledge:'Tài liệu',reference:'Reference',storyboard:'Storyboard AI'})[a.category]||'Tài nguyên')}</button><div class="resource-body"><h3>${esc(a.name)}</h3><p>${esc(a.description||'Chưa có mô tả. Thêm ghi chú để agent hiểu tư liệu.').slice(0,110)}</p><div class="resource-meta"><span>${bytes(a.size)} · ${a.episodeId?'Theo tập':'Toàn dự án'}</span><button class="icon-button" data-action="asset-detail" data-id="${esc(a.id)}" aria-label="Chi tiết tài nguyên">${icon('chevron')}</button></div></div></article>`;}
const KNOWLEDGE_SAMPLES=[{title:'Âm thanh của cuộc sống',kind:'technique',tags:'ASMR, room tone, âm thanh',note:'Ghi 30–60 giây room tone tại mỗi bối cảnh. Đặt micro gần hành động nhưng ngoài khung, kiểm tra bằng tai nghe. Lấy tiếng nước, chổi, dao và bát đũa riêng; ưu tiên âm thanh thật thay vì phủ nhạc cả tập.'},{title:'Ánh sáng tự nhiên, cảm xúc thật',kind:'technique',tags:'ánh sáng, cửa sổ, golden hour',note:'Khảo sát hướng cửa sổ và hiên theo từng giờ. Dùng ánh sáng bên hoặc chếch sau để làm rõ chất liệu gỗ, lá và hơi nước. Tránh ánh nắng trực diện gắt; tấm hắt trắng có thể đủ cho cận cảnh trong nhà.'},{title:'Học cách kể, giữ câu chuyện riêng',kind:'reference',tags:'reference, nhịp kể, bố cục',note:'Khi lưu video đối thủ, ghi URL, timecode, cỡ cảnh, thời lượng, chuyển động và âm thanh bạn quan sát. Tách nguyên tắc kỹ thuật khỏi nội dung đặc trưng của họ. Dùng nguyên tắc đó cho bối cảnh và câu chuyện riêng của dự án.'}];
function renderKnowledge(){const refs=state.references.filter(r=>(filter==='all'||r.kind===filter)&&(!query||[r.title,r.note,r.tags,r.source,...(r.shots||[]).flatMap(s=>[s.title,s.note,s.size,s.move,s.timecode])].join(' ').toLowerCase().includes(query.toLowerCase())));return heading('Gom cảm hứng. Tích lũy cách làm.','Một trí nhớ chung cho cả đội: tinh thần dự án, cách quay, reference và những điều bạn học được.',button('add-reference','Thêm kiến thức','plus','primary'),'KNOWLEDGE & INSPIRATION')+`<div class="toolbar"><div class="filter-tabs">${[['all','Tất cả'],['technique','Kỹ thuật quay'],['reference','Kênh & video'],['production','Sản xuất']].map(([id,t])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search-input" aria-label="Tìm kiến thức" placeholder="Tìm tri thức, reference…" value="${esc(query)}"></label></div><div class="content-grid">${refs.length?refs.map(r=>referenceCard(r)).join(''):empty('book',query?'Chưa có kết quả phù hợp':'Một trí nhớ chung đang chờ được lấp đầy',query?'Thử tìm theo kỹ thuật, kênh hoặc tag.':'Lưu video yêu thích kèm timecode và phân tích, hoặc ghi lại quy tắc quay mà ekip muốn sử dụng.',query?'':'add-reference','Thêm kiến thức đầu tiên')}</div>${!state.references.length&&!query?`<div class="section-label" style="margin-top:28px"><h2>Những trang đầu tiên</h2><span>Gợi ý kiến thức từ studio</span></div><div class="content-grid">${KNOWLEDGE_SAMPLES.map((r,i)=>`<article class="panel ref-card"><div class="ref-top">${icon(['volume','sun','film'][i])}${pill('HƯỚNG DẪN MẪU','gray')}</div><h3 style="font-size:13px;font-weight:500;margin-bottom:12px">${r.title}</h3><p class="text-small muted" style="min-height:115px">${r.note}</p>${button('edit-knowledge-sample','Thêm ảnh & lưu','image','small',`data-index="${i}"`)}</article>`).join('')}</div>`:''}<div class="instruction">${icon('link')} Mỗi reference có ảnh minh họa, video gốc, danh sách shot theo timecode và ghi chú. Codex nhận cả phân tích và ID ảnh để đọc khi làm việc. URL video chưa được tự động xem hoặc chép lời.</div>`;}
function referenceCard(r){const k={technique:'Kỹ thuật quay',reference:'Kênh & video',production:'Sản xuất'};return `<article class="panel ref-card"><div class="ref-top">${icon(r.kind==='reference'?'film':r.kind==='technique'?'camera':'clipboard')}${pill(k[r.kind]||'Kiến thức')}</div><h3 style="font-size:13px;font-weight:500">${esc(r.title)}</h3>${referencePreview(r,state)}<p class="text-small muted">${esc(r.note).slice(0,210)}${r.note.length>210?'…':''}</p><div class="tags">${String(r.tags||'').split(',').filter(Boolean).map(t=>`<span>${esc(t.trim())}</span>`).join('')}</div><div class="resource-meta"><span>${esc(r.timecode||'Toàn tài liệu')} · ${r.episodeId?'Theo tập':'Toàn dự án'}</span><button class="icon-button" data-action="reference-detail" data-id="${esc(r.id)}" aria-label="Mở reference">${icon('chevron')}</button></div></article>`;}
function renderTeam(){return heading('Một đội ngũ, một tinh thần.','Năm chuyên môn bổ trợ cho nhau. Bạn là nhà sản xuất và người duyệt cuối cùng.','','MEET YOUR CREATIVE CREW')+`<div class="content-grid">${AGENTS.map(a=>`<article class="panel agent-full">${avatar(a)}<h3>${a.name}</h3><div class="role">${a.role}</div><p>${a.mission}</p><div class="tags">${a.skills.map(s=>`<span>${s}</span>`).join('')}</div>${button('agent-detail','Làm quen với '+a.name,'arrow','small',`data-id="${a.id}"`)}</article>`).join('')}<article class="panel agent-full" style="background:#f0f3e7"><div style="color:#98ab80">${icon('compass')}</div><h3>Bạn</h3><div class="role">Nhà sản xuất · Chủ dự án</div><p>Bổ sung chất liệu thực tế, góp ý với các cộng sự và duyệt từng bản bàn giao. Mọi quyết định sáng tạo cuối cùng nằm trong tay bạn.</p><div class="tags"><span>Định hướng</span><span>Phản hồi</span><span>Phê duyệt</span></div>${button('open-studio','Vào bàn chuyện','message','small')}</article></div><section class="panel form-panel" style="margin-top:24px"><h2>Những chuyên môn nên bổ sung khi dự án lớn hơn</h2><div class="two"><ul class="info-list"><li>${icon('book')}Quản lý tri thức: chuẩn hóa nguồn, phiên bản và phạm vi sử dụng tư liệu.</li><li>${icon('clipboard')}Trợ lý sản xuất: khảo sát, lịch nắng, đạo cụ, lịch quay và call sheet.</li></ul><ul class="info-list"><li>${icon('eye')}Continuity & kiểm tra khả thi: đối chiếu nhân vật, trục máy, tiến độ công việc.</li><li>${icon('film')}Biên tập & khán giả quốc tế: nhịp dựng, phụ đề EN, tiêu đề, thumbnail và phản hồi sau phát hành.</li></ul></div><p class="text-small muted">Đây là đề xuất mở rộng. Bản đầu gộp các kiểm tra này vào năm agent chính, giúp giảm vòng bàn giao và chi phí.</p></section>`;}
function renderSettings(){return heading('Giữ chung một tinh thần.','Những nguyên tắc này là nền tảng để cả đội phát triển từng tập phim.','','PROJECT FOUNDATIONS')+`<div class="settings-layout"><section class="panel form-panel"><h2>Thông tin & trí nhớ dự án</h2><form id="project-form"><div class="form-group"><label for="project-name">Tên dự án</label><input id="project-name" name="name" value="${esc(state.project.name)}" required maxlength="100"></div><div class="form-row"><div class="form-group"><label for="project-audience">Khán giả hướng tới</label><input id="project-audience" name="audience" value="${esc(state.project.audience)}" maxlength="180"></div><div class="form-group"><label for="project-duration">Thời lượng mục tiêu</label><input id="project-duration" name="duration" value="${esc(state.project.duration)}" maxlength="60"></div></div><div class="form-group"><label for="project-language">Ngôn ngữ & cách kể</label><input id="project-language" name="language" value="${esc(state.project.language)}" maxlength="180"></div><div class="form-group"><label for="project-bible">Project bible · Trí nhớ chung</label><textarea id="project-bible" name="bible" rows="10" maxlength="20000">${esc(state.project.bible)}</textarea><small>Tinh thần, nhân vật, bối cảnh, bảng màu, âm thanh, điều nên và không nên làm. Thay đổi nền tảng sẽ đưa các hồ sơ đã tạo về đầu quy trình để duyệt lại; phiên bản cũ được giữ.</small></div><button type="submit" class="btn primary">${icon('check')}Lưu nền tảng dự án</button></form></section><div><section class="panel form-panel appearance-settings"><h2>Giao diện & không gian</h2><p class="text-small muted">Chọn ánh sáng phù hợp khi làm việc. Xưởng 3D đổi ánh sáng theo giao diện.</p><div class="form-group"><label for="theme-preference">Chế độ hiển thị</label><select id="theme-preference"><option value="system">Theo hệ thống</option><option value="light">Giao diện sáng</option><option value="dark">Giao diện tối</option></select><small>Lựa chọn được ghi nhớ trên trình duyệt này.</small></div></section><section class="panel form-panel" style="margin-top:20px"><h2>Codex ↔ Xưởng Chibi</h2>${pill(config.bridgeReady?'Cầu nối MCP sẵn sàng':'Chưa kết nối kho lưu trữ',config.bridgeReady?'':'amber')}<p class="text-small muted" style="margin:17px 0">Mọi công việc sáng tạo thực hiện trong Codex. Xưởng tạo đầu việc, cung cấp tư liệu và đồng bộ kết quả. Không cần API key mô hình.</p><ul class="info-list"><li>${icon('send')}Giao việc trong Studio → sao chép yêu cầu sang Codex.</li><li>${icon('link')}Cài plugin riêng của Site để Codex đọc và nộp kết quả đúng tài khoản.</li><li>${icon('clock')}Chỉ khi Codex nhận việc, nhân vật mới hiện trạng thái đang làm.</li><li>${icon('lock')}Kết quả luôn dừng chờ bạn duyệt. Codex không tự chuyển bước.</li></ul><div class="row" style="margin-top:17px"><a href="/install.html" target="_blank" rel="noopener" class="btn primary">${icon('book')}Hướng dẫn cài đặt</a><a href="https://github.com/vanhungtq/valley-chibi-studio" target="_blank" rel="noopener" class="btn">GitHub</a></div></section><section class="panel form-panel" style="margin-top:20px"><h2>Dữ liệu của bạn</h2><p class="text-small muted">Kịch bản và tri thức lưu trong D1. Tư liệu lưu riêng theo tài khoản. ${config.storageProvider==='kv'?'Bản KV miễn phí: tối đa 20 MiB mỗi tệp, 1 GB và 1.000 lượt ghi/ngày dùng chung tài khoản Cloudflare. Tệp mới có thể chờ đồng bộ 60 giây hoặc hơn.':'Giới hạn tệp: '+uploadLimitLabel()+'.'} JSON sao lưu không chứa nội dung nhị phân.</p><div style="display:flex;gap:8px;flex-wrap:wrap">${button('download-json','Sao lưu JSON','download','small')}${button('import-json','Nhập bản sao lưu','upload','small')}</div><p class="license-note">Ảnh mood chỉ là minh họa. Thư viện nguồn và kỹ thuật nên ghi rõ xuất xứ để đội ngũ có thể kiểm tra lại.</p></section></div></div>`;}
function renderScript(ep){const s=ep.scenes.find(s=>s.id===sceneId)||ep.scenes[0];if(!s)return empty('pen','Kịch bản đang chờ được viết','Thêm brief và tư liệu, sau đó duyệt định hướng và concept. Biên kịch sẽ lập phân cảnh ở bước thứ ba.','open-studio','Về studio');return `${ep.sample?`<div class="hint-banner subtle">${icon('info')}<span>Kịch bản mẫu để khám phá cách làm việc. Chưa dựa trên khảo sát hay ảnh hiện trường của bạn.</span></div>`:''}${ep.stale?'<div class="hint-banner">'+icon('history')+'<span>Brief hoặc nền tảng đã thay đổi. Đây là bản nháp trước đó; cần chạy lại và duyệt các bước phụ thuộc.</span></div>':''}<div class="script-layout"><nav class="panel scene-nav" aria-label="Danh sách phân cảnh">${ep.scenes.map(sc=>`<button data-scene="${esc(sc.id)}" class="${s.id===sc.id?'active':''}"><strong>${esc(sc.id)}</strong>${esc(sc.title)}<span>${sc.shots.length} shots · ${mmss(sc.shots.reduce((n,x)=>n+x.seconds,0))}</span></button>`).join('')}</nav><section class="panel script-detail"><div class="scene-heading"><div><div class="eyebrow">PHÂN CẢNH ${esc(s.id)}</div><h2>${esc(s.title)}</h2><p>${esc(s.location)} · ${esc(s.time)}</p></div>${pill(esc(s.emotion))}</div><div class="scene-summary">${esc(s.summary)}</div><div class="scene-sound">${icon('volume')}<span>${esc(s.sound)}</span></div><div class="section-label"><h2>Shot list chi tiết</h2><span>${s.shots.length} shots · ${mmss(s.shots.reduce((n,x)=>n+x.seconds,0))}</span></div>${s.shots.map(sh=>`<article class="shot-item"><span class="shot-num">${esc(sh.id)}</span><div><h3>${esc(sh.action)}</h3><div class="shot-specs"><span>${esc(sh.size)}</span><span>${esc(sh.lens)} FF</span><span>${esc(sh.move)}</span><span>${sh.seconds}s</span></div><p class="shot-notes">${icon('sun')} ${esc(sh.light)}<br>${icon('volume')} ${esc(sh.sound)}${sh.note?'<br>'+icon('message')+' '+esc(sh.note):''}</p>${sh.assetIds?.length?`<p class="shot-notes">${icon('paperclip')} ${sh.assetIds.map(id=>esc(state.assets.find(a=>a.id===id)?.name||id)).join(', ')}</p>`:''}</div><button class="icon-button" data-action="shot-detail" data-id="${esc(sh.id)}" aria-label="Sửa shot ${esc(sh.id)}">${icon('edit')}</button></article>`).join('')}</section></div>`;}
function renderBoards(ep){if(!countShots(ep))return empty('board','Storyboard bắt đầu từ kịch bản','Biên kịch cần tạo phân cảnh và đạo diễn hình ảnh cần thiết kế shot trước khi dựng storyboard.','open-studio','Về studio');const scenes=boardScene==='all'?ep.scenes:ep.scenes.filter(s=>s.id===boardScene);return `<div class="toolbar"><div class="filter-tabs"><button data-board-scene="all" class="${boardScene==='all'?'active':''}">Tất cả · ${countShots(ep)}</button>${ep.scenes.map((s,i)=>`<button data-board-scene="${esc(s.id)}" class="${boardScene===s.id?'active':''}">Cảnh ${i+1}</button>`).join('')}</div><div class="row wrap">${button('storyboard-prompts','Tạo ảnh bằng ChatGPT','sparkles','primary')}${button('import-storyboard','Nhập ảnh 4 shot','crop','small')}${button('download-book','Tải storyboard','download','small')}</div></div><div class="hint-banner subtle">${icon('crop')}<span>Tạo một ảnh ChatGPT 2×2 cho 4 shot, rồi nhập ảnh để cắt thành từng khung. Ảnh AI được gắn nhãn riêng; khung chưa tạo ảnh vẫn dùng sơ đồ minh họa.</span></div><div class="storyboard-grid">${scenes.flatMap(s=>s.shots.map(sh=>{const board=boardAsset(state,ep,sh),a=board?.asset;return `<article class="panel"><div class="board-image">${a?boardMarkup(board):storyboardSvg(s,sh)}<span class="board-number">${esc(sh.id)}</span><span class="board-type">${a?(board.generated?'STORYBOARD AI':'ẢNH THAM KHẢO'):'CHƯA CÓ ẢNH STORYBOARD'}</span></div><div class="board-info"><h3>${esc(sh.action)}</h3><div class="shot-specs"><span>${esc(sh.size)}</span><span>${esc(sh.lens)}</span><span>${sh.seconds}s</span></div><div class="board-bottom"><span>${esc(s.id)} · ${esc(sh.move)}</span><button data-action="shot-detail" data-id="${esc(sh.id)}">${icon(a?'edit':'paperclip')}${a?'Chi tiết':'Gắn tư liệu'}</button>${a?button('download-shot-image','Tải ảnh','download','small',`data-id="${esc(sh.id)}"`):''}</div></div></article>`;})).join('')}</div>`;}
function renderDeliverables(ep){return `<div class="export-grid"><section class="panel"><div class="book-preview"><div class="book-paper"><div class="book-logo"><img src="/assets/mark.svg" alt="">VALLEY STUDIO</div><div class="book-episode">PRODUCTION BOOK · EPISODE ${String(ep.number).padStart(2,'0')}</div><h2>${esc(ep.title)}</h2><p>${esc(ep.englishTitle||'A story from the countryside')}</p><img src="/assets/valley.jpg" alt="Ảnh mood tham khảo"><div class="book-bottom"><span>${ep.scenes.length} SCENES · ${countShots(ep)} SHOTS</span><span>${ep.stage>=5?'APPROVED':'PRE-PRODUCTION DRAFT'}</span></div></div></div><div class="panel-head"><h2>Hồ sơ quay hoàn chỉnh</h2>${pill(ep.stage>=5?'Đã duyệt':'Bản nháp',ep.stage>=5?'':'amber')}</div></section><div><div class="section-label"><h2>Mang câu chuyện ra hiện trường</h2></div><div class="export-list"><button class="panel export-option" data-action="download-book">${icon('book')}<div><strong>Production book · HTML</strong><small>Kịch bản, storyboard, shot list, lịch dự kiến và checklist. Mở offline, in thành PDF.</small></div>${icon('download')}</button><button class="panel export-option" data-action="print-book">${icon('print')}<div><strong>In / Lưu PDF</strong><small>Hồ sơ ngang A4, hình ảnh được nhúng vào tài liệu. Chọn “Save as PDF” trong cửa sổ in.</small></div>${icon('chevron')}</button><button class="panel export-option" data-action="download-csv">${icon('list')}<div><strong>Shot list · CSV</strong><small>${countShots(ep)} shot có ID, thông số máy, ánh sáng và âm thanh. Mở bằng Excel / Sheets.</small></div>${icon('download')}</button><button class="panel export-option" data-action="download-json">${icon('folder')}<div><strong>Bản sao dự án · JSON</strong><small>Nội dung, phiên bản và metadata của toàn dự án. Tệp thư viện lưu riêng.</small></div>${icon('download')}</button></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>${icon('history')}Lịch sử phiên bản</h2><small>${ep.versions.length} bản</small></div>${ep.versions.length?ep.versions.slice().reverse().slice(0,6).map(v=>`<button class="history-item" style="width:100%;text-align:left" data-action="version-detail" data-id="${esc(v.id)}"><span><strong>${esc(v.label)}</strong><br>${fmtDate(v.at)} · ${fmtTime(v.at)}</span>${icon('chevron')}</button>`).join(''):'<div class="file-row"><small>Phiên bản được lưu khi bạn duyệt hoặc yêu cầu sửa.</small></div>'}</section><p class="license-note">Xuất hồ sơ hiện tại sẽ giữ rõ trạng thái bản nháp / đã duyệt. Hình minh họa được gắn nhãn, không được coi là khảo sát thực tế.</p></div></div>`;}

function modal(title,content,wide=false){returnFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay" data-overlay="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div><div class="modal-body">${content}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal input:not([type=hidden]),.modal textarea,.modal button')?.focus(),20);}
function closeModal(){if(modalCtx.boardUrl)URL.revokeObjectURL(modalCtx.boardUrl);document.querySelector('#modal-root').innerHTML='';document.body.style.overflow='';modalCtx={};if(returnFocus?.isConnected)returnFocus.focus();}
function showBrief(isNew=false){const ep=current();modalCtx={type:isNew?'new-episode':'brief'};modal(isNew?'Bắt đầu một câu chuyện mới':'Brief · Hạt giống của tập phim',`<form id="brief-form"><div class="form-group"><label for="ep-title">Tên tập phim</label><input id="ep-title" name="title" value="${isNew?'':esc(ep.title)}" placeholder="Ví dụ: Mùa mận đầu tiên" required maxlength="160"></div><div class="form-group"><label for="ep-english">Tên tiếng Anh · tùy chọn</label><input id="ep-english" name="englishTitle" value="${isNew?'':esc(ep.englishTitle||'')}" placeholder="A New Beginning in Plum Valley" maxlength="180"></div><div class="form-group"><label for="ep-brief">Câu chuyện bạn muốn kể</label><textarea id="ep-brief" name="brief" rows="7" required maxlength="20000" placeholder="Nhân vật là ai? Điều gì diễn ra? Bạn muốn người xem cảm thấy thế nào?">${isNew?'':esc(ep.brief)}</textarea><small>Ý tưởng thô là đủ. Thêm bối cảnh thật và điều ekip làm được để agent phát triển đúng hướng.</small></div>${!isNew&&Object.keys(ep.outputs).length?'<div class="hint-banner">'+icon('history')+'<span>Sửa brief sẽ lưu bản hiện tại vào lịch sử và đưa quy trình về bước định hướng để duyệt lại.</span></div>':''}<div class="modal-foot">${button('close-modal','Để sau')}<button type="submit" class="btn primary">${icon(isNew?'plus':'check')}${isNew?'Tạo tập phim':'Lưu brief'}</button></div></form>`);}
function selectAgent(id){selected=id;render();showAgent(id);}
function showAgent(id){const a=AGENTS.find(a=>a.id===id);if(!a)return;modalCtx={agent:id};const status=agentStatus(a,current());modal(a.role,`<div class="agent-modal-top">${avatar(a)}<div><h3>${a.name}</h3><p>${a.role}</p></div><span class="spacer"></span>${pill(status.text,status.cls==='wait'?'amber':'')}</div><p>${a.mission}</p><div class="tags">${a.skills.map(s=>`<span>${s}</span>`).join('')}</div><h3 style="font-size:11px;font-weight:500;margin-top:25px">Tài liệu bàn giao</h3><div class="output-document">${a.deliverable}</div><p class="text-small muted">${a.instruction}</p><div class="modal-foot">${button('chat-with-agent','Gửi ghi chú cho '+a.name,'message','primary',`data-id="${a.id}"`)}</div>`);}
function stageDetail(stage){const ep=current(),o=ep.outputs[stage];if(!o){const a=AGENTS[stage];modal(STAGES[stage],`<div class="agent-modal-top">${avatar(a)}<div><h3>${a.name}</h3><p>${a.role}</p></div></div><p>${a.mission}</p><div class="instruction">Bước ${stage+1} chỉ bắt đầu sau khi bạn duyệt bản bàn giao ở bước trước. ${stage===ep.stage?'Bước này đã sẵn sàng.':'Bước này chưa có tài liệu bàn giao.'}</div><div class="modal-foot">${button('close-modal','Đã hiểu')}${stage===ep.stage?button('run-codex','Giao việc cho Codex','play','primary'):''}</div>`);return;}
 const approved=ep.approved.includes(stage);modalCtx={stage};modal(o.title,`<div class="row" style="margin-bottom:16px">${pill(approved?'Đã duyệt':'Chờ bạn duyệt',approved?'':'amber')}${pill(o.mode==='sample'?'Nội dung mẫu':o.mode==='codex'?'Kết quả từ Codex':'Bản lưu trước',o.mode==='sample'?'gray':'')}<span class="spacer"></span><span class="text-small muted">${fmtDate(o.at)} · ${fmtTime(o.at)}</span></div><h3 class="output-title">${esc(o.title)}</h3><p class="output-summary">${esc(o.summary)}</p><div class="output-document">${esc(o.content)}</div>${o.missing?.length?'<h3 style="font-size:12px;font-weight:500">Những điều cần xác nhận</h3><ul class="missing-list">'+o.missing.map(m=>`<li>${esc(m)}</li>`).join('')+'</ul>':''}${o.sources?.length?`<p class="text-small muted">Nguồn: ${o.sources.map(id=>{const a=state.assets.find(a=>a.id===id)||state.references.find(r=>r.id===id);return esc(a?.name||a?.title||id);}).join(' · ')}</p>`:'<p class="text-small muted">Chưa có nguồn từ tư liệu thực tế được trích dẫn.</p>'}<div class="approval-footer">${!approved&&stage===ep.stage?button('approve-stage','Duyệt & bàn giao','check','primary',`data-stage="${stage}"`):''}${button('revise-stage','Yêu cầu chỉnh sửa','edit','',`data-stage="${stage}"`)}${button('download-output','Tải tài liệu','download','',`data-stage="${stage}"`)}</div>`,true);}
function showRevision(stage){modalCtx={stage};modal('Góp ý · '+STAGES[stage],`<form id="revision-form"><p class="text-small muted">Nêu điều bạn muốn thay đổi. Bản hiện tại được lưu vào lịch sử; các bước phụ thuộc sẽ được mở lại để duyệt.</p><div class="form-group"><label for="revision-text">Góp ý cho ${AGENTS[stage].name}</label><textarea id="revision-text" name="text" rows="5" required maxlength="8000" placeholder="Ví dụ: Giảm công việc cải tạo, thêm khoảnh khắc hai chị em kết nối…"></textarea></div><div class="modal-foot">${button('close-modal','Để sau')}<button class="btn primary" type="submit">${icon('send')}Lưu góp ý & mở lại bước</button></div></form>`);}
function archive(ep,label){ep.versions.push({id:uid(),label,at:new Date().toISOString(),snapshot:structuredClone({brief:ep.brief,stage:ep.stage,outputs:ep.outputs,approved:ep.approved,scenes:ep.scenes,storyboards:ep.storyboards||{}})});if(ep.versions.length>30)ep.versions.shift();}
function invalidate(ep,from){for(const k of Object.keys(ep.outputs))if(Number(k)>=from)delete ep.outputs[k];ep.approved=ep.approved.filter(s=>s<from);ep.stage=from;ep.stale=from<=3;}
async function approve(stage){if(running)return;const ep=current();if(stage!==ep.stage||!ep.outputs[stage])return;const ok=await mutate(()=>{const e=current();e.approved.push(stage);e.stage=stage+1;archive(e,'Duyệt '+STAGES[stage]);e.activity.push({id:uid(),agent:AGENTS[stage].id,text:'Bạn đã duyệt '+STAGES[stage].toLowerCase()+'. '+(stage<4?'Đã bàn giao cho '+AGENTS[stage+1].name+'.':'Hồ sơ sẵn sàng để xuất cho ekip.'),at:new Date().toISOString(),kind:'approval'});},stage===4?'Hồ sơ đã được duyệt. Sẵn sàng xuất cho ekip.':'Đã duyệt và bàn giao cho '+AGENTS[Math.min(stage+1,4)].name+'.');if(ok)closeModal();}
async function run(mode){
 const ep=current();if(running||saving||localRun)return;if(ep.stage>=5){toast('Hồ sơ đã hoàn tất.');return;}if(ep.outputs[ep.stage]){stageDetail(ep.stage);return;}if(!serverReady){toast('Đăng nhập để lưu và giao việc cho Codex.',true);return;}
 closeModal();localRun=true;
 try{await persist();if(mode==='codex'){const result=await api('/api/tasks',{method:'POST',body:JSON.stringify({episodeId:ep.id})});codexTasks=[result.task,...codexTasks.filter(t=>t.id!==result.task.id)];toast('Đã giao việc. Đang chờ phiên Codex nhận.');render();showCodexTask(result.task.id);}else{running=AGENTS[ep.stage].id;render();const result=await api('/api/run',{method:'POST',body:JSON.stringify({episodeId:ep.id,mode:'sample'})});state=result.state;revision=result.revision;toast('Bản mẫu đã bàn giao. Hãy xem và duyệt để tiếp tục.');}}
 catch(error){toast(error.message,true);if(error.status===409){try{const fresh=await api('/api/state');state=fresh.state;revision=fresh.revision;}catch{}}}
 finally{running=null;localRun=false;render();}
}
function codexTaskCard(t){const paused=t.displayStatus==='interrupted';return `<div class="codex-task-box"><div class="row">${icon(paused?'pause':t.status==='running'?'clock':'clipboard')}<strong>${paused?'Phiên Codex cần tiếp tục':t.status==='running'?'Codex đang thực hiện':'Đang chờ Codex nhận việc'}</strong></div><p>${esc(t.progress||'Mở Codex có plugin của Xưởng và yêu cầu nhận đầu việc này.')}</p><div class="row">${button('copy-codex-prompt','Sao chép yêu cầu','message','small',`data-id="${esc(t.id)}"`)}${button('connect-codex','Đổi Codex','refresh','small',`data-id="${esc(t.id)}"`)}<button class="icon-button" data-action="refresh-tasks" aria-label="Đồng bộ tiến độ">${icon('refresh')}</button></div></div>`;}
function codexPrompt(id){return codexConnectionPrompt({mcpUrl:config.mcpUrl,projectName:state.project.name,episodeId:current().id,taskId:id});}
async function copyCodexPrompt(id){try{await navigator.clipboard.writeText(codexPrompt(id));toast('Đã sao chép yêu cầu. Dán vào Codex có plugin Xưởng.');}catch{download('Yeu-cau-Codex-'+id.slice(0,8)+'.txt',codexPrompt(id));toast('Đã tải yêu cầu Codex dạng TXT.');}}
function showCodexTask(id){const t=codexTasks.find(t=>t.id===id);if(!t)return;const statuses={queued:'Chờ Codex nhận',running:'Codex đang thực hiện',awaiting_review:'Chờ bạn duyệt',approved:'Đã duyệt',cancelled:'Đã hủy',error:'Cần xử lý lỗi',stale:'Đầu vào đã thay đổi',changes_requested:'Yêu cầu sửa'};modal('Đầu việc · '+STAGES[t.stage],`${pill(t.displayStatus==='interrupted'?'Phiên cần tiếp tục':statuses[t.status]||t.status,t.status==='queued'?'gray':'')}<p>Công việc được thực hiện trong phiên Codex của bạn. Xưởng lưu dữ liệu, đồng bộ trạng thái và nhận tài liệu. Bấm giao việc không tự khởi chạy một phiên Codex.</p><div class="output-document">${esc(codexPrompt(t.id))}</div><p class="text-small muted">${esc(t.progress||'Chưa có phiên Codex nhận việc.')}<br>ID: ${esc(t.id)}<br>Cập nhật: ${fmtDate(t.updatedAt)} · ${fmtTime(t.updatedAt)}</p><div class="modal-foot">${button('connect-codex','Kết nối / đổi Codex','cloud','',`data-id="${esc(t.id)}"`)}${['queued','running'].includes(t.status)?button('cancel-task','Hủy đầu việc','close','',`data-id="${esc(t.id)}"`):''}${button('download-task','Tải gói đầu việc','download','',`data-id="${esc(t.id)}"`)}${button('copy-codex-prompt','Sao chép yêu cầu','message','primary',`data-id="${esc(t.id)}"`)}</div><p class="license-note">Cài plugin riêng của Xưởng trong ChatGPT để dùng các công cụ đồng bộ. Hướng dẫn: <a href="/install.html" target="_blank" rel="noopener">Cài đặt & vận hành</a>.</p>`);}

function showCodexConnection(id){
 const task=codexTasks.find(t=>t.id===id)||(!id?activeTask():null);
 const episode=state.episodes.find(e=>e.id===task?.episodeId)||current();
 const prompt=codexConnectionPrompt({mcpUrl:config.mcpUrl,projectName:serverReady?state.project.name:'',episodeId:serverReady?episode.id:'',taskId:task?.id});
 modalCtx={connectionPrompt:prompt};
 modal('Kết nối & tiếp tục ở Codex khác',`<p>Dùng cùng một Xưởng với nhiều tài khoản Codex/ChatGPT. Mỗi tài khoản kết nối riêng và cấp quyền bằng cùng GitHub chủ Xưởng; dự án và file đã đồng bộ được giữ trên Cloudflare.</p>${config.mcpUrl?`<div class="form-group"><label for="codex-mcp-url">URL MCP của Xưởng này</label><input id="codex-mcp-url" value="${esc(config.mcpUrl)}" readonly><small>Remote MCP · Streamable HTTP · OAuth</small></div><ol class="info-list"><li>Trong tài khoản Codex/ChatGPT mới, thêm kết nối MCP bằng URL trên và đăng nhập GitHub của bạn.</li><li>Sao chép yêu cầu bên dưới vào phiên mới để đọc lại dự án và phần việc đã lưu.</li><li>Tiếp tục đầu việc rồi nộp kết quả về cùng Xưởng để bạn duyệt.</li></ol>`:'<p>Xưởng này dùng kết nối plugin của nền tảng hosting. Kết nối đúng plugin hiện có trong tài khoản mới; xem hướng dẫn cài đặt của Xưởng.</p>'}${task?`<div class="instruction"><strong>${esc(STAGES[task.stage])} · ${esc(episode.title)}</strong><p>${esc(task.progress||'Đang chờ Codex nhận việc.')}</p><p>${task.artifacts.length} file đã đồng bộ · ID: ${esc(task.id)}</p>${task.status==='running'?`<p>Bàn giao sẽ kết thúc quyền nhận việc của phiên cũ, giữ lại tiến độ và file đã lưu để phiên mới nhận ngay.</p>${button('handoff-task','Bàn giao sang Codex khác','refresh','',`data-id="${esc(task.id)}"`)}`:''}</div>`:''}<p class="text-small muted">Chat và file chưa lưu về Xưởng không tự chuyển tài khoản. Không cần tạo lại Worker, D1, KV hay GitHub OAuth App khi đổi Codex.</p><details><summary>Xem yêu cầu tiếp tục công việc</summary><div class="output-document">${esc(prompt)}</div></details><div class="modal-foot">${config.mcpUrl?button('copy-mcp-url','Sao chép URL MCP','clipboard'):''}${button('copy-connection-prompt','Sao chép yêu cầu tiếp tục','message','primary')}</div><p class="license-note"><a href="${config.mcpUrl?'/resume.html':'/install.html'}" target="_blank" rel="noopener">Hướng dẫn kết nối và đổi tài khoản</a>. Kết nối riêng cần được tài khoản/workspace mới hỗ trợ.</p>`,true);
}

function showWorkflow(){modal('Từ một ý tưởng đến một ngày quay',`<p>Bạn và năm cộng sự cùng làm việc theo một quy trình có điểm dừng rõ ràng.</p><ul class="info-list">${AGENTS.map((a,i)=>`<li>${icon(a.icon)}<span><strong>${i+1}. ${a.role}</strong><br>${a.deliverable} → Bạn duyệt → Bàn giao bước tiếp.</span></li>`).join('')}</ul><div class="instruction">Gửi góp ý tại mỗi mốc để tạo phiên bản mới. Thay đổi brief sẽ mở lại các bước phụ thuộc. Mô hình 3D, nhãn trạng thái, nhật ký và tài liệu cùng đọc từ tiến độ của tập phim.</div><p>Tập mẫu dùng nội dung minh họa được chuẩn bị sẵn. Nút “Giao việc cho Codex” tạo đầu việc chờ phiên Codex nhận qua plugin MCP của Xưởng. Xưởng không gọi API mô hình.</p><div class="modal-foot"><a class="btn" href="/research.html" target="_blank" rel="noopener">Nghiên cứu & kiến trúc</a>${button('close-modal','Bắt đầu khám phá','arrow','primary')}</div>`);}
function showShot(id){const ep=current();let scene,shot;for(const s of ep.scenes){const sh=s.shots.find(sh=>sh.id===id);if(sh){scene=s;shot=sh;break;}}if(!shot)return;modalCtx={shotId:id,sceneId:scene.id};const resources=state.assets.filter(a=>!a.episodeId||a.episodeId===ep.id);modal('Chi tiết shot · '+esc(id),`<form id="shot-form">${ep.storyboards?.[id]?`<div class="shot-board-preview">${boardMarkup(boardAsset(state,ep,shot))}</div><p>${button('remove-storyboard','Gỡ storyboard AI','close','small',`data-id="${esc(id)}"`)}</p>`:''}<div class="form-row"><div class="form-group"><label>Cỡ cảnh</label><input name="size" value="${esc(shot.size)}" required maxlength="60"></div><div class="form-group"><label>Tiêu cự tương đương full frame</label><input name="lens" value="${esc(shot.lens)}" required maxlength="60"></div></div><div class="form-row"><div class="form-group"><label>Chuyển động</label><input name="move" value="${esc(shot.move)}" required maxlength="100"></div><div class="form-group"><label>Thời lượng dựng · giây</label><input name="seconds" value="${shot.seconds}" type="number" min="1" max="600" required></div></div><div class="form-group"><label>Hành động & bố cục</label><textarea name="action" rows="3" required maxlength="4000">${esc(shot.action)}</textarea></div><div class="form-row"><div class="form-group"><label>Ánh sáng</label><textarea name="light" rows="2" maxlength="1000">${esc(shot.light)}</textarea></div><div class="form-group"><label>Âm thanh</label><textarea name="sound" rows="2" maxlength="1000">${esc(shot.sound)}</textarea></div></div><div class="form-group"><label for="shot-asset">Ảnh / tư liệu gắn với shot</label><select name="asset" id="shot-asset" multiple size="5"><option value="">Chưa gắn — dùng sơ đồ minh họa</option>${resources.map(a=>`<option value="${esc(a.id)}" ${shot.assetIds?.includes(a.id)?'selected':''}>${esc(a.name)}</option>`).join('')}</select><small>Tải ảnh trong Thư viện tài nguyên trước. Giữ Ctrl / Command để chọn nhiều tư liệu. Ảnh đầu tiên được dùng trong storyboard và production book.</small></div><div class="form-group"><label>Ghi chú cho ekip</label><textarea name="note" rows="2" maxlength="2000">${esc(shot.note||'')}</textarea></div>${ep.outputs[4]?'<div class="hint-banner">'+icon('history')+'<span>Chỉnh shot sẽ mở lại bước thiết kế hồ sơ để duyệt bản cập nhật.</span></div>':''}<div class="modal-foot">${button('close-modal','Để sau')}<button type="submit" class="btn primary">${icon('check')}Lưu shot</button></div></form>`,true);}
function showUpload(files){if(!files?.length)return;if(running||uploading||saving){toast('Vui lòng đợi tác vụ hiện tại hoàn tất.');return;}if(!serverReady){toast('Cần đăng nhập và kết nối kho lưu trữ để tải tư liệu.',true);return;}const list=[...files].slice(0,20);if(list.some(f=>!f.size||f.size>uploadLimit())){toast('Mỗi tệp phải lớn hơn 0 và không quá '+uploadLimitLabel()+'.',true);return;}modalCtx={files:list};modal('Thêm chất liệu vào thư viện',`<form id="upload-form"><p class="text-small muted">${list.map(f=>esc(f.name)+' · '+bytes(f.size)).join('<br>')}</p><div class="form-row"><div class="form-group"><label>Phân loại</label><select name="category"><option value="context">Bối cảnh</option><option value="character">Nhân vật</option><option value="prop">Đạo cụ</option><option value="knowledge">Tài liệu / Kiến thức</option><option value="reference">Reference</option><option value="storyboard">Storyboard AI</option></select></div><div class="form-group"><label>Phạm vi sử dụng</label><select name="scope"><option value="episode">Tập ${String(current().number).padStart(2,'0')} · ${esc(current().title)}</option><option value="project" ${scope==='project'?'selected':''}>Dùng chung toàn dự án</option></select></div></div><div class="form-group"><label>Mô tả · Điều agent cần biết</label><textarea name="description" rows="4" maxlength="6000" placeholder="Ví dụ: Ảnh mặt tiền nhà lúc 7 giờ sáng. Cửa chính hướng đông, hiên thấp…"></textarea></div><div class="form-group"><label>Tags · phân cách bằng dấu phẩy</label><input name="tags" maxlength="300" placeholder="nhà gỗ, sáng sớm, cửa chính"></div><div class="modal-foot">${button('close-modal','Để sau')}<button type="submit" class="btn primary">${icon('upload')}Tải ${list.length} tài nguyên</button></div></form>`);}
async function uploadSubmit(form){const files=modalCtx.files;if(!files?.length)return;const data=new FormData(form),epId=data.get('scope')==='episode'?current().id:null;const uploaded=[];uploading=true;modal('Đang lưu tài nguyên',`<div class="upload-progress"><span class="spinner"></span><span id="upload-status">Chuẩn bị tải lên ${files.length} tệp…</span></div><p>Giữ cửa sổ này mở đến khi hoàn tất.</p>`);try{for(let i=0;i<files.length;i++){const node=document.querySelector('#upload-status');if(node)node.textContent='Đang tải '+(i+1)+'/'+files.length+': '+files[i].name;const body=new FormData();body.set('file',files[i]);const a=await api('/api/files',{method:'POST',body});uploaded.push({...a,category:data.get('category'),episodeId:epId,description:data.get('description'),tags:data.get('tags'),createdAt:new Date().toISOString()});}state.assets.push(...uploaded);try{await persist();}catch(error){state.assets=state.assets.filter(a=>!uploaded.some(x=>x.id===a.id));throw error;}closeModal();toast('Đã lưu '+uploaded.length+' tài nguyên vào thư viện.');}catch(error){for(const a of uploaded)try{await api('/api/files/'+a.id,{method:'DELETE'});}catch{}toast(error.message,true);closeModal();}finally{uploading=false;render();}}
function showAsset(id){const a=state.assets.find(a=>a.id===id);if(!a)return;modalCtx={assetId:id};modal('Tư liệu · '+esc(a.name),`${a.mime.startsWith('image/')?`<img class="asset-preview" src="${esc(a.url)}" alt="${esc(a.name)}">`:a.mime.startsWith('video/')?`<video class="asset-preview" controls src="${esc(a.url)}"></video>`:''}<form id="asset-form"><div class="form-group"><label>Tên tài nguyên</label><input name="name" value="${esc(a.name)}" required maxlength="240"></div><div class="form-row"><div class="form-group"><label>Phân loại</label><select name="category">${[['context','Bối cảnh'],['character','Nhân vật'],['prop','Đạo cụ'],['knowledge','Tài liệu'],['reference','Reference'],['storyboard','Storyboard AI']].map(([id,t])=>`<option value="${id}" ${a.category===id?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-group"><label>Phạm vi</label><select name="episodeId"><option value="">Toàn dự án</option>${state.episodes.map(e=>`<option value="${esc(e.id)}" ${e.id===a.episodeId?'selected':''}>Tập ${e.number} · ${esc(e.title)}</option>`).join('')}</select></div></div><div class="form-group"><label>Mô tả</label><textarea name="description" rows="4" maxlength="6000">${esc(a.description||'')}</textarea></div><div class="form-group"><label>Tags</label><input name="tags" value="${esc(a.tags||'')}" maxlength="300"></div><div class="resource-meta"><a href="${esc(a.url)}" target="_blank" rel="noopener" class="ref-link">${icon('external')}Mở tệp gốc · ${bytes(a.size)}</a><button type="button" data-action="delete-asset" data-id="${esc(a.id)}" style="font-size:9px;color:#b68c72">Xóa tài nguyên</button></div><div class="modal-foot">${button('close-modal','Đóng')}<button type="submit" class="btn primary">${icon('check')}Lưu thông tin</button></div></form>`);}
function showReference(id,draft){const r=draft||structuredClone(state.references.find(r=>r.id===id)||{kind:'technique',title:'',note:'',url:'',source:'',tags:'',timecode:'',episodeId:null,imageIds:[],videoId:'',shots:[]});modalCtx={referenceId:id,refDraft:r};modal(id?'Kiến thức & phân tích video':'Thêm kiến thức / video mẫu',referenceEditor(r,state,uploadLimit()),true);}
function updateReferenceDraft(){const form=document.querySelector('#reference-form');return form?collectReference(form,modalCtx.refDraft):modalCtx.refDraft;}

function setupDrop(){const el=document.querySelector('#upload-drop');if(!el)return;el.addEventListener('dragover',ev=>{ev.preventDefault();el.classList.add('dragover');});el.addEventListener('dragleave',()=>el.classList.remove('dragover'));el.addEventListener('drop',ev=>{ev.preventDefault();el.classList.remove('dragover');showUpload(ev.dataTransfer.files);});}
function showExport(){modal('Mang câu chuyện ra hiện trường',`<div class="export-list"><button class="panel export-option" data-action="download-book">${icon('book')}<div><strong>Production book · HTML</strong><small>Toàn bộ kịch bản, storyboard, lịch quay dự kiến và checklist.</small></div>${icon('download')}</button><button class="panel export-option" data-action="print-book">${icon('print')}<div><strong>In / Lưu PDF</strong><small>Mở bản in A4 ngang, lưu PDF trong hộp thoại in.</small></div>${icon('chevron')}</button><button class="panel export-option" data-action="download-csv">${icon('list')}<div><strong>Shot list · CSV</strong><small>Thông số quay và ghi chú để ekip quản lý trên bảng tính.</small></div>${icon('download')}</button><button class="panel export-option" data-action="download-json">${icon('folder')}<div><strong>Bản sao dự án · JSON</strong><small>Nội dung và metadata, không gồm tệp nhị phân trong thư viện.</small></div>${icon('download')}</button></div><p class="license-note">Hồ sơ hiện tại: ${current().approved.length}/5 mốc được duyệt. ${current().sample?'Đây là tập mẫu; hình minh họa chưa phải hiện trường.':''}</p>`);}
async function printBook(){const win=window.open('','_blank');if(!win){toast('Cho phép mở cửa sổ để in hồ sơ.',true);return;}win.document.write('<p style="font-family:Arial;padding:40px;color:#778866">Đang dàn trang hồ sơ quay…</p>');try{const html=await productionBook(state,current());win.document.open();win.document.write(html);win.document.close();await new Promise(resolve=>setTimeout(resolve,700));win.focus();win.print();}catch(error){win.close();toast('Chưa thể tạo bản in. Thử tải bản HTML.',true);}}

function showStoryboardPrompts(){const batches=storyboardBatches(current());modal('Storyboard bằng ảnh ChatGPT',`<p>Tạo tối đa 4 shot trong một ảnh 2×2, giữ cùng nhân vật và bối cảnh. Dán yêu cầu vào phiên ChatGPT này hoặc giao bước Designer cho Codex sau khi duyệt shot list.</p><p class="text-small muted">Số ảnh dự kiến: ${batches.length}. Số lần tạo ảnh giảm; chi phí/token thực tế tùy công cụ và độ phân giải. Sau khi tạo có thể nhập ảnh và cắt tự động.</p>${batches.map((batch,i)=>`<section class="reference-shot"><h3>Ảnh ${i+1} · ${batch.map(x=>esc(x.shot.id)).join(' / ')}</h3><div class="output-document">${esc(storyboardPrompt(state.project,current(),batch))}</div>${button('copy-storyboard-prompt','Sao chép yêu cầu','clipboard','small',`data-index="${i}"`)}</section>`).join('')}<div class="modal-foot">${button('import-storyboard','Nhập ảnh & cắt 4 shot','crop','primary')}</div>`,true);}
function showStoryboardImport(){const ep=current(),batches=storyboardBatches(ep);modalCtx={type:'storyboard-import'};modal('Nhập ảnh ChatGPT · Cắt 4 shot',`<form id="storyboard-import-form"><p>Chọn ảnh có bốn ô bằng nhau, không viền hoặc rãnh. Xưởng cắt theo thứ tự trên trái → trên phải → dưới trái → dưới phải và lưu riêng từng shot.</p><div class="form-group"><label for="storyboard-batch">Nhóm shot</label><select id="storyboard-batch">${batches.map((g,i)=>`<option value="${i}">Ảnh ${i+1} · ${g.map(x=>esc(x.shot.id)).join(', ')}</option>`).join('')}</select></div><div class="form-row">${panelNames.map((name,i)=>`<div class="form-group"><label>${name}</label><select name="panel-${i}"><option value="">Bỏ qua ô này</option>${shots(ep).map(s=>`<option value="${esc(s.id)}">${esc(s.id)} · ${esc(s.action.slice(0,55))}</option>`).join('')}</select></div>`).join('')}</div><div class="form-group"><label for="storyboard-file">Ảnh contact sheet 2×2 · tối đa ${uploadLimitLabel()}</label><input id="storyboard-file" type="file" accept="image/jpeg,image/png,image/webp" required></div><div id="storyboard-import-preview" class="storyboard-import-preview"></div><p class="text-small muted">Ảnh AI là dự kiến quay. Lưu ảnh mới sẽ mở lại bước hồ sơ Designer nếu đã có bản bàn giao, để bạn duyệt lại.</p><div class="modal-foot">${button('close-modal','Để sau')}<button type="submit" class="btn primary">Cắt & lưu từng shot</button></div></form>`,true);setStoryboardImportBatch(0);}
function setStoryboardImportBatch(index){const group=storyboardBatches(current())[index]||[];panelNames.forEach((_,i)=>{const el=document.querySelector(`[name="panel-${i}"]`);if(el)el.value=group[i]?.shot.id||'';});}
async function uploadMediaFile(file,category,episodeId,description){if(!file?.size||file.size>uploadLimit())throw new Error('Mỗi tệp phải lớn hơn 0 và không quá '+uploadLimitLabel()+'.');const form=new FormData();form.set('file',file);const a=await api('/api/files',{method:'POST',body:form});return {...a,category,episodeId,description:description||'',tags:category==='storyboard'?'storyboard, ChatGPT, AI':'reference',createdAt:new Date().toISOString()};}
async function saveMediaChange(prepare,message){if(!serverReady){toast('Cần đăng nhập và kết nối kho lưu trữ.',true);return;}if(uploading||saving||running){toast('Vui lòng chờ tác vụ đang xử lý.',true);return;}const previous=structuredClone(state),uploaded=[];uploading=true;const form=document.querySelector('.modal form');if(form)for(const el of form.querySelectorAll('button,input,select,textarea'))el.disabled=true;try{await prepare(uploaded);state.assets.push(...uploaded);await persist();closeModal();toast(message);}catch(error){state=previous;for(const a of uploaded)try{await api('/api/files/'+a.id,{method:'DELETE'});}catch{}if(error.status===409)try{const fresh=await api('/api/state');state=fresh.state;revision=fresh.revision;}catch{}toast(error.message,true);if(form?.isConnected)for(const el of form.querySelectorAll('button,input,select,textarea'))el.disabled=false;}finally{uploading=false;render();}}
async function importStoryboardForm(form){const file=document.querySelector('#storyboard-file')?.files?.[0],data=new FormData(form),ids=panelNames.map((_,i)=>String(data.get('panel-'+i)||'')),chosen=ids.filter(Boolean);if(!file||!chosen.length||new Set(chosen).size!==chosen.length){toast('Chọn ảnh và 1–4 shot khác nhau.',true);return;}if(file.size>uploadLimit()){toast('Ảnh tối đa '+uploadLimitLabel()+'.',true);return;}const epId=current().id;await saveMediaChange(async uploaded=>{const parts=await splitStoryboard(file),ep=state.episodes.find(e=>e.id===epId);if(ep.outputs[4]){archive(ep,'Trước khi thay storyboard AI');invalidate(ep,4);}ep.storyboards??={};for(let i=0;i<4;i++){if(!ids[i])continue;const a=await uploadMediaFile(new File([parts[i]],ids[i]+'-storyboard.jpg',{type:'image/jpeg'}),'storyboard',ep.id,'Storyboard AI ChatGPT · '+ids[i]+' · cắt ô '+panelNames[i]);uploaded.push(a);ep.storyboards[ids[i]]={assetId:a.id,panel:null,generated:true};}},'Đã cắt và lưu '+chosen.length+' ảnh storyboard.');}
async function saveReferenceForm(form){const r=collectReference(form,modalCtx.refDraft),id=modalCtx.referenceId;if(!r.title){toast('Hãy điền tiêu đề kiến thức.',true);return;}if(r.url&&!/^https?:\/\//i.test(r.url)){toast('URL nguồn cần bắt đầu bằng http:// hoặc https://.',true);return;}const allFiles=[...(r.pendingFiles||[]),...r.shots.map(s=>s.pendingFile).filter(Boolean)];if(allFiles.some(f=>!f.size||f.size>uploadLimit())){toast('Mỗi tệp phải lớn hơn 0 và không quá '+uploadLimitLabel()+'.',true);return;}if((r.pendingFiles||[]).filter(f=>f.type.startsWith('video/')).length>1){toast('Mỗi reference chọn một video gốc.',true);return;}const linkedIds=[...(r.imageIds||[]),r.videoId,...r.shots.map(s=>s.imageId)].filter(Boolean);if(linkedIds.some(id=>{const a=state.assets.find(a=>a.id===id);return !a||(a.episodeId&&a.episodeId!==r.episodeId);})){toast('Ảnh/video đang gắn khác phạm vi. Hãy gỡ liên kết hoặc chọn lại phạm vi.',true);return;}await saveMediaChange(async uploaded=>{for(const file of r.pendingFiles||[]){const a=await uploadMediaFile(file,'reference',r.episodeId,r.title);uploaded.push(a);if(a.mime.startsWith('image/'))r.imageIds.push(a.id);else if(a.mime.startsWith('video/'))r.videoId=a.id;}for(const sh of r.shots){if(sh.pendingFile){const a=await uploadMediaFile(sh.pendingFile,'reference',r.episodeId,r.title+' · '+(sh.title||sh.timecode||sh.id));uploaded.push(a);sh.imageId=a.id;}delete sh.pendingFile;}delete r.pendingFiles;r.imageIds=[...new Set(r.imageIds)];if(id)Object.assign(state.references.find(x=>x.id===id),r);else state.references.push({...r,id:uid(),createdAt:new Date().toISOString()});},'Đã lưu kiến thức, ảnh và phân tích từng shot cho Codex.');}
async function captureReferenceFrame(){const video=document.querySelector('#reference-video');if(!video||video.readyState<2){toast('Hãy tải và dừng video tại khung muốn lấy.',true);return;}try{const r=updateReferenceDraft();if(r.shots.length>=200)throw new Error('Mỗi reference tối đa 200 shot.');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));if(!blob)throw new Error('Chưa thể chụp khung hình.');const at=mmss(Math.floor(video.currentTime));r.shots.push({id:uid(),title:'Khung hình '+at,timecode:at,size:'',lens:'',move:'',note:'',imageId:'',pendingFile:new File([blob],'shot-'+Math.floor(video.currentTime)+'.jpg',{type:'image/jpeg'})});showReference(modalCtx.referenceId,r);}catch(e){toast(e.message,true);}}
async function downloadShotImage(id){try{const sh=shots(current()).find(s=>s.id===id),b=boardAsset(state,current(),sh);if(!b)return;const response=await fetch(b.asset.url);if(!response.ok)throw new Error('Chưa thể tải ảnh gốc.');let blob=await response.blob();if(b.panel!==null&&b.panel!==undefined)blob=(await splitStoryboard(blob))[b.panel];download(id+'-storyboard.'+(blob.type==='image/png'?'png':'jpg'),blob,blob.type);}catch(e){toast(e.message,true);}}

document.addEventListener('click',async ev=>{
 const target=ev.target.closest('[data-action],[data-page],[data-tab],[data-agent],[data-collab],[data-filter],[data-scene],[data-board-scene]');
 if(!target){if(ev.target.dataset.overlay&&!uploading)closeModal();return;}
 if(target.disabled||uploading)return;
 if(target.dataset.page){navigate(target.dataset.page);return;}
 if(target.dataset.tab){tab=target.dataset.tab;render();return;}
 if(target.dataset.agent){selectAgent(target.dataset.agent);return;}
 if(target.dataset.collab){collabTab=target.dataset.collab;render();return;}
 if(target.dataset.filter){filter=target.dataset.filter;render();return;}
 if(target.dataset.scene){sceneId=target.dataset.scene;render();return;}
 if(target.dataset.boardScene){boardScene=target.dataset.boardScene;render();return;}
 const action=target.dataset.action,id=target.dataset.id,stage=Number(target.dataset.stage);
 switch(action){
 case 'close-modal':if(!uploading)closeModal();break;
 case 'logout':{try{await api(config.logoutUrl,{method:'POST',body:'{}'});location.reload();}catch(e){toast(e.message,true);}}break;
 case 'toggle-theme':toggleTheme();break;
 case 'toggle-scene-motion':scene3d?.toggleMotion();refreshSceneControls();break;
 case 'auto-orbit':scene3d?.toggleOrbit();refreshSceneControls();break;
 case 'fullscreen-scene':{const panel=document.querySelector('.scene-panel');try{if(document.fullscreenElement)await document.exitFullscreen();else if(panel?.requestFullscreen)await panel.requestFullscreen();else toast('Trình duyệt này chưa hỗ trợ toàn màn hình.',true);}catch{toast('Chưa thể mở toàn màn hình trong cửa sổ này.',true);}}break;
 case 'menu':document.querySelector('#sidebar')?.classList.toggle('open');break;
 case 'close-nav':document.querySelector('#sidebar')?.classList.remove('open');break;
 case 'project':navigate('settings');break;
 case 'help':case 'workflow-info':showWorkflow();break;
 case 'account':modal('Không gian riêng của bạn',`<p>Dự án được gắn với tài khoản ${config.authProvider==='github'?'GitHub':'ChatGPT'} đang đăng nhập. Mỗi tài khoản có dữ liệu và kho tệp riêng.</p>${pill(config.signedIn?'Đã đăng nhập':'Đang xem trước',config.signedIn?'':'amber')}<div class="modal-foot">${button('close-modal','Đóng')}${config.signedIn&&config.logoutUrl?button('logout','Đăng xuất','lock'):''}${!config.signedIn?'<a class="btn primary" href="/signin-with-chatgpt?return_to=/" target="_top">Đăng nhập</a>':''}</div>`);break;
 case 'notifications':collabTab='activity';page='studio';tab='studio';render();break;
 case 'open-studio':page='studio';tab='studio';location.hash='studio';render();closeModal();break;
 case 'go-settings':navigate('settings');break;
 case 'new-episode':showBrief(true);break;
 case 'edit-brief':showBrief(false);break;
 case 'open-episode':{const ok=await mutate(()=>{state.activeEpisode=id;},'');if(ok){page='studio';tab='studio';sceneId=current().scenes[0]?.id||'SC01';location.hash='studio';render();}}break;
 case 'switch-episode':modal('Chọn câu chuyện',`<div class="export-list">${state.episodes.map(e=>`<button class="panel export-option" data-action="open-episode-modal" data-id="${esc(e.id)}">${icon('film')}<div><strong>Tập ${e.number} · ${esc(e.title)}</strong><small>${e.approved.length}/5 mốc đã duyệt ${e.sample?'· Tập mẫu':''}</small></div>${icon(e.id===state.activeEpisode?'check':'chevron')}</button>`).join('')}</div><div class="modal-foot">${button('new-episode','Tạo tập mới','plus','primary')}</div>`);break;
 case 'open-episode-modal':{const ok=await mutate(()=>{state.activeEpisode=id;},'');if(ok){closeModal();sceneId=current().scenes[0]?.id||'SC01';render();}}break;
 case 'zoom-in':scene3d?.zoom(.1);break;
 case 'zoom-out':scene3d?.zoom(-.1);break;
 case 'reset-scene':scene3d?.reset();refreshSceneControls();break;
 case 'agent-detail':showAgent(id);break;
 case 'chat-with-agent':selected=id;page='studio';tab='studio';closeModal();render();document.querySelector('#note-text')?.focus();break;
 case 'note-preset':draftNote=target.dataset.text||'';render();document.querySelector('#note-text')?.focus();break;
 case 'stage-detail':stageDetail(stage);break;
 case 'review-current':stageDetail(current().stage);break;
 case 'revise-current':showRevision(current().stage);break;
 case 'revise-stage':showRevision(stage);break;
 case 'approve-stage':await approve(stage);break;
 case 'run-codex':await run('codex');break;
 case 'codex-task':showCodexTask(id||activeTask()?.id);break;
 case 'connect-codex':showCodexConnection(id);break;
 case 'copy-mcp-url':{try{await navigator.clipboard.writeText(config.mcpUrl);toast('Đã sao chép URL MCP của Xưởng.');}catch{download('Valley-MCP-URL.txt',config.mcpUrl);toast('Đã tải URL MCP.');}}break;
 case 'copy-connection-prompt':{try{await navigator.clipboard.writeText(modalCtx.connectionPrompt);toast('Đã sao chép. Dán yêu cầu vào tài khoản Codex mới.');}catch{download('Valley-Tiep-tuc-Codex.txt',modalCtx.connectionPrompt);toast('Đã tải yêu cầu tiếp tục.');}}break;
 case 'handoff-task':{try{const result=await api('/api/tasks/'+id+'/handoff',{method:'POST',body:'{}'});codexTasks=[result.task,...codexTasks.filter(t=>t.id!==id)];render();showCodexConnection(id);toast('Đã bàn giao. Phiên Codex mới có thể nhận việc ngay.');}catch(e){toast(e.message,true);}}break;
 case 'copy-codex-prompt':await copyCodexPrompt(id);break;
 case 'download-task':{try{const packet=await api('/api/tasks/'+id);download('Valley-Codex-Task-'+id.slice(0,8)+'.json',JSON.stringify(packet,null,2),'application/json');}catch(e){toast(e.message,true);}}break;
 case 'cancel-task':{try{await api('/api/tasks/'+id+'/cancel',{method:'POST',body:'{}'});await syncRunStatus();closeModal();toast('Đã hủy đầu việc. Kết quả cũ của tác vụ sẽ không được tiếp nhận.');}catch(e){toast(e.message,true);}}break;
 case 'refresh-tasks':await syncRunStatus();break;
 case 'run-sample':await run('sample');break;
 case 'upload':document.querySelector('#resource-files')?.click();break;
 case 'asset-detail':showAsset(id);break;
 case 'shot-detail':showShot(id);break;
 case 'add-reference':showReference();break;
 case 'add-reference-shot':{const r=updateReferenceDraft();if(r.shots.length>=200){toast('Mỗi reference tối đa 200 shot.',true);break;}r.shots.push({id:uid(),title:'',timecode:'',size:'',lens:'',move:'',note:'',imageId:''});showReference(modalCtx.referenceId,r);}break;
 case 'remove-reference-shot':{const r=updateReferenceDraft();r.shots=r.shots.filter(s=>s.id!==id);showReference(modalCtx.referenceId,r);}break;
 case 'move-reference-shot':{const r=updateReferenceDraft(),i=r.shots.findIndex(s=>s.id===id),j=i+Number(target.dataset.direction);if(j>=0&&j<r.shots.length)[r.shots[i],r.shots[j]]=[r.shots[j],r.shots[i]];showReference(modalCtx.referenceId,r);}break;
 case 'capture-reference-frame':await captureReferenceFrame();break;
 case 'storyboard-prompts':showStoryboardPrompts();break;
 case 'copy-storyboard-prompt':{const group=storyboardBatches(current())[Number(target.dataset.index)];if(!group)break;const text=storyboardPrompt(state.project,current(),group);try{await navigator.clipboard.writeText(text);toast('Đã sao chép yêu cầu tạo ảnh ChatGPT.');}catch{download('Storyboard-'+group[0].shot.id+'.txt',text);}}break;
 case 'import-storyboard':showStoryboardImport();break;
 case 'download-shot-image':await downloadShotImage(id);break;
 case 'remove-storyboard':{const ok=await mutate(()=>{const e=current();if(e.outputs[4]){archive(e,'Trước khi gỡ storyboard');invalidate(e,4);}delete e.storyboards[id];},'Đã gỡ ảnh storyboard khỏi shot.');if(ok)closeModal();}break;
 case 'reference-detail':showReference(id);break;
 case 'edit-knowledge-sample':{const sample=KNOWLEDGE_SAMPLES[Number(target.dataset.index)];showReference(undefined,{...sample,url:'',source:'Hướng dẫn mẫu của studio',timecode:'',episodeId:null,imageIds:[],videoId:'',shots:[]});}break;
 case 'save-knowledge':await mutate(()=>{const sample=KNOWLEDGE_SAMPLES[Number(target.dataset.index)];state.references.push({...sample,id:uid(),url:'',timecode:'',episodeId:null,source:'Hướng dẫn mẫu của studio',createdAt:new Date().toISOString()});},'Đã lưu hướng dẫn vào trí nhớ chung.');break;
 case 'delete-reference':{const ok=await mutate(()=>{state.references=state.references.filter(r=>r.id!==id);},'Đã xóa kiến thức khỏi thư viện.');if(ok)closeModal();}break;
 case 'delete-asset':{const a=state.assets.find(a=>a.id===id);if(!a)return;modalCtx={assetId:id};modal('Xóa tài nguyên?',`<p>${esc(a.name)} sẽ được gỡ khỏi thư viện và các shot liên kết. Các phiên bản cũ vẫn giữ metadata nhưng không thể mở lại tệp đã xóa.</p><div class="modal-foot">${button('close-modal','Giữ lại')}${button('confirm-delete-asset','Xóa tài nguyên','trash','danger',`data-id="${esc(id)}"`)}</div>`);}break;
 case 'confirm-delete-asset':{const a=state.assets.find(a=>a.id===id);const ok=await mutate(()=>{state.assets=state.assets.filter(a=>a.id!==id);for(const e of state.episodes){for(const s of e.scenes)for(const sh of s.shots)sh.assetIds=(sh.assetIds||[]).filter(x=>x!==id);for(const [shot,b] of Object.entries(e.storyboards||{}))if(b.assetId===id)delete e.storyboards[shot];}for(const r of state.references){r.imageIds=(r.imageIds||[]).filter(x=>x!==id);if(r.videoId===id)r.videoId='';for(const sh of r.shots||[])if(sh.imageId===id)sh.imageId='';}},'Đã gỡ tài nguyên khỏi thư viện.');if(ok){try{await api('/api/files/'+id,{method:'DELETE'});}catch{toast('Đã gỡ liên kết. Kho tệp chưa xác nhận xóa tệp gốc.',true);}closeModal();}}break;
 case 'export-menu':showExport();break;
 case 'download-book':target.disabled=true;toast('Đang dàn trang và nhúng hình vào hồ sơ…');try{await exportBook(state,current());toast('Đã tạo production book. Mở tệp HTML để xem hoặc in.');}catch{toast('Chưa thể xuất hồ sơ. Thử lại sau.',true);}finally{target.disabled=false;}break;
 case 'print-book':await printBook();break;
 case 'download-csv':download('Valley-Studio-Tap-'+current().number+'-Shot-List.csv',shotCsv(current()),'text/csv;charset=utf-8');toast('Đã xuất shot list CSV.');break;
 case 'download-json':download('Valley-Studio-Project-Backup.json',projectJson(state),'application/json');toast('Đã tạo bản sao nội dung dự án.');break;
 case 'download-output':{const o=current().outputs[stage];if(o)download('Valley-Studio-'+STAGES[stage]+'.txt',o.title+'\n\n'+o.content+'\n\nCẦN XÁC NHẬN\n'+(o.missing||[]).join('\n'));}break;
 case 'import-json':document.querySelector('#import-json')?.click();break;
 case 'confirm-import':{const data=modalCtx.importState;if(!data)return;const ok=await mutate(()=>{state=data;},'Đã nhập nội dung dự án.');if(ok)closeModal();}break;
 case 'version-detail':{const v=current().versions.find(v=>v.id===id);if(v)modal(v.label,`<p class="text-small muted">${fmtDate(v.at)} · ${fmtTime(v.at)} · ${v.snapshot.approved.length}/5 mốc tại thời điểm lưu.</p><div class="output-document">${esc(v.snapshot.brief)}</div>${Object.entries(v.snapshot.outputs).map(([s,o])=>`<h3 style="font-size:13px;font-weight:500">${esc(o.title)}</h3><div class="output-document">${esc(o.content)}</div>`).join('')}<div class="modal-foot">${button('download-version','Tải phiên bản JSON','download','primary',`data-id="${esc(id)}"`)}</div>`,true);}break;
 case 'download-version':{const v=current().versions.find(v=>v.id===id);if(v)download('Valley-Studio-Version-'+v.id.slice(0,8)+'.json',JSON.stringify(v,null,2),'application/json');}break;
 }
});
document.addEventListener('submit',async ev=>{
 const form=ev.target;if(!['note-form','brief-form','revision-form','shot-form','upload-form','asset-form','reference-form','project-form','storyboard-import-form'].includes(form.id))return;ev.preventDefault();
 if(running||saving||uploading){toast('Vui lòng chờ tác vụ hiện tại hoàn tất.');return;}
 const data=new FormData(form);const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
 switch(form.id){
 case 'note-form':{const text=document.querySelector('#note-text').value.trim();if(!text)break;const ok=await mutate(()=>{const e=current(),at=new Date().toISOString();e.notes.push({id:uid(),agent:selected,text,at});e.activity.push({id:uid(),agent:selected,text,at,kind:'note'});},'Đã lưu ghi chú. Agent sẽ đọc ở lần chạy tiếp theo.');if(ok){draftNote='';render();}}break;
 case 'brief-form':{const context=modalCtx.type;const title=String(data.get('title')).trim(),brief=String(data.get('brief')).trim();if(!title||!brief){toast('Hãy điền tên tập và ý tưởng.',true);break;}const ok=await mutate(()=>{if(context==='new-episode'){const ep=seedEpisode();Object.assign(ep,{id:uid(),number:Math.max(0,...state.episodes.map(e=>e.number))+1,title,englishTitle:data.get('englishTitle')||'',brief,sample:false,scenes:[],activity:[{id:uid(),agent:'ceo',text:'Tập phim đã được tạo. Hãy bổ sung tư liệu và chạy bước định hướng để bắt đầu.',kind:'system',at:new Date().toISOString()}]});state.episodes.push(ep);state.activeEpisode=ep.id;}else{const e=current();if(e.brief!==brief&&Object.keys(e.outputs).length){archive(e,'Trước khi sửa brief');invalidate(e,0);}if(e.brief!==brief){e.sample=false;e.stale=e.scenes.length>0;}e.title=title;e.englishTitle=data.get('englishTitle')||'';e.brief=brief;}},context==='new-episode'?'Đã gieo mầm một tập phim mới.':'Đã lưu brief của tập.');if(ok){closeModal();page='studio';tab='studio';render();}}break;
 case 'revision-form':{const stage=modalCtx.stage,text=String(data.get('text')).trim();if(!text)break;const ok=await mutate(()=>{const e=current();archive(e,'Yêu cầu sửa '+STAGES[stage]);invalidate(e,stage);const at=new Date().toISOString();e.notes.push({id:uid(),agent:AGENTS[stage].id,text,at});e.activity.push({id:uid(),agent:AGENTS[stage].id,text:'Góp ý cho '+STAGES[stage]+': '+text,at,kind:'note'});},'Đã lưu góp ý. Chạy lại bước '+STAGES[stage].toLowerCase()+' khi sẵn sàng.');if(ok)closeModal();}break;
 case 'shot-form':{const id=modalCtx.shotId;const ok=await mutate(()=>{const e=current();if(e.outputs[4]){archive(e,'Trước khi sửa shot '+id);invalidate(e,4);}const sh=shots(e).find(s=>s.id===id);for(const field of ['size','lens','move','action','light','sound','note'])sh[field]=String(data.get(field)||'').trim();sh.seconds=Number(data.get('seconds'));sh.assetIds=data.getAll('asset').filter(Boolean);},'Đã cập nhật shot và storyboard.');if(ok)closeModal();}break;
 case 'upload-form':await uploadSubmit(form);break;
 case 'asset-form':{const id=modalCtx.assetId;const ok=await mutate(()=>{const a=state.assets.find(a=>a.id===id);for(const f of ['name','category','description','tags'])a[f]=String(data.get(f)||'').trim();a.episodeId=data.get('episodeId')||null;},'Đã cập nhật thông tin tư liệu.');if(ok)closeModal();}break;
 case 'reference-form':await saveReferenceForm(form);break;
 case 'storyboard-import-form':await importStoryboardForm(form);break;
 case 'project-form':{const ok=await mutate(()=>{const changed=state.project.bible!==data.get('bible')||state.project.audience!==data.get('audience')||state.project.language!==data.get('language')||state.project.duration!==data.get('duration');if(changed)for(const ep of state.episodes)if(Object.keys(ep.outputs).length){archive(ep,'Trước khi sửa nền tảng');invalidate(ep,0);}for(const f of ['name','audience','duration','language','bible'])state.project[f]=String(data.get(f)||'').trim();},'Đã lưu trí nhớ chung của dự án.');}break;
 }
 if(submit?.isConnected)submit.disabled=false;
});
document.addEventListener('input',ev=>{if(ev.target.id==='note-text')draftNote=ev.target.value;if(ev.target.id==='search-input'){query=ev.target.value;const start=ev.target.selectionStart;render();const input=document.querySelector('#search-input');input?.focus();input?.setSelectionRange(start,start);}});
document.addEventListener('change',async ev=>{
 if(ev.target.id==='theme-preference'){setTheme(ev.target.value);return;}
 if(ev.target.name==='episodeId'&&ev.target.closest('#reference-form')){const r=updateReferenceDraft();showReference(modalCtx.referenceId,r);return;}
 if(ev.target.name==='videoId'&&ev.target.closest('#reference-form')){const r=updateReferenceDraft();showReference(modalCtx.referenceId,r);return;}
 if(ev.target.id==='storyboard-batch'){setStoryboardImportBatch(Number(ev.target.value));return;}
 if(ev.target.id==='storyboard-file'){if(modalCtx.boardUrl)URL.revokeObjectURL(modalCtx.boardUrl);const file=ev.target.files?.[0];modalCtx.boardUrl=file?URL.createObjectURL(file):'';const preview=document.querySelector('#storyboard-import-preview');if(preview)preview.innerHTML=file?`<img src="${esc(modalCtx.boardUrl)}" alt="Ảnh 2×2 được cắt theo thứ tự trên trái, trên phải, dưới trái, dưới phải">`:'';return;}
 if(ev.target.id==='asset-scope'){scope=ev.target.value;render();}if(ev.target.id==='resource-files'){showUpload(ev.target.files);ev.target.value='';}if(ev.target.id==='import-json'){const file=ev.target.files[0];ev.target.value='';if(!file)return;if(file.size>2*1024*1024){toast('Bản sao lưu vượt quá 2 MB.',true);return;}try{const parsed=JSON.parse(await file.text()),importState=parsed.state;if(parsed.format!=='valley-studio-backup'||importState?.schema!==1||!Array.isArray(importState.episodes)||!importState.episodes.length||!importState.project)throw new Error();modalCtx={importState};modal('Nhập nội dung dự án?',`<p>Bản sao “${esc(importState.project.name)}” có ${importState.episodes.length} tập phim. Thao tác này thay thế nội dung dự án đang mở. Nên tải một bản sao JSON của dữ liệu hiện tại trước khi nhập.</p><p class="text-small muted">Các tệp nhị phân không nằm trong JSON. Liên kết thư viện chỉ hoạt động với tài khoản đã tải tệp gốc.</p><div class="modal-foot">${button('download-json','Sao lưu hiện tại','download')}${button('confirm-import','Nhập bản sao','upload','primary')}</div>`);}catch{toast('Tệp không phải bản sao hợp lệ của Valley Studio.',true);}}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!uploading){closeModal();document.querySelector('#sidebar')?.classList.remove('open');}if(ev.key==='Tab'){const modal=document.querySelector('.modal');if(!modal)return;const nodes=[...modal.querySelectorAll('button:not(:disabled),a[href],input:not([type=hidden]),textarea,select')];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(PAGES[next]&&page!==next){page=next;filter='all';query='';render();}});
async function syncRunStatus(){
 if(!serverReady||localRun||saving||uploading||document.querySelector('.modal form')||page==='settings')return;
 try{const status=await api('/api/tasks');const fresh=await api('/api/state');const changed=JSON.stringify(status.tasks)!==JSON.stringify(codexTasks)||fresh.revision!==revision;codexTasks=status.tasks;state=fresh.state;revision=fresh.revision;const pending=activeTask();running=pending?.status==='running'&&pending.displayStatus!=='interrupted'?pending.agent:null;if(changed)render();}catch{}
}
render();load().then(syncRunStatus);setInterval(syncRunStatus,5000);

const kvImageRetries=new WeakMap();
document.addEventListener('error',event=>{const img=event.target;if(config.storageProvider!=='kv'||img?.tagName!=='IMG')return;let source;try{source=new URL(img.currentSrc||img.src,location.origin);}catch{return;}if(source.origin!==location.origin||!source.pathname.startsWith('/api/files/'))return;const count=kvImageRetries.get(img)||0;if(count>=8)return;kvImageRetries.set(img,count+1);setTimeout(()=>{if(!img.isConnected)return;source.searchParams.set('kv_retry',String(count+1));img.src=source.href;},count<2?5000:10000);},true);
document.addEventListener('load',event=>{if(event.target?.tagName==='IMG')kvImageRetries.delete(event.target);},true);
